// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":365,"question":"لدي بستانٌ وقفٌ محدودٌ بحدودٍ معروفةٍ، وهناك أرض فضاء بيني وبين جاري، واتفقتُ مع جاري وأدخلناها في الوقف، ما مدى صحَّة ذلك؟","title":"حكم إدخال أرض بين جارين في وقف بستان","answer":"الجواب: إذا كانت الأرض لكما واصطلحتما عليها فلا بأس، أو كانت ميتةً لا حقَّ فيها لأحدٍ، وإدخالكما لها في الوقف لا يضرُّ أحدًا: ليست طريقًا للناس، وليس للناس فيها حاجة، وهي ميتة، واصطلحتم عليها؛ لا بأس بهذا.  أما إن كانت للناس فيها حاجة، أو كانت لأحدٍ من الناس مملوكة؛ فليس عليكم التَّعدي عليها.","link":"https://binbaz.org.sa/fatwas/4615/حكم-ادخال-ارض-بين-جارين-في-وقف-بستان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0420.mp3","categories":["الوقف"]},{"id":840,"question":"المصاحف الموقوفة في بيت الله هل يجوز أخذها والقراءة بها –يعني: خارج المسجد؟","title":"حكم أخذ المصحف الموقوف خارج المسجد","answer":"الجواب:\nالأقرب لا يجوز؛ لأن الواقف أراد بقاءها في المسجد حتى ينتفع بها المصلون والقارئون الذين يأتون المسجد لأجل ذلك.\nالأظهر والأقرب أنه لا يجوز أخذها، هذا هو ظاهر كلام أهل العلم، وهو الأظهر من حيث الدليل؛ لأن هذا معناه التَّوسعة للناس بأن يأخذوا المصاحف من المساجد، أو من المكتبات، ويستحلُّوها لأنفسهم، أو مدة طويلة يُعطلها عن الناس، لا يجوز هذا، يقرأ في المسجد فقط، أما أن يخرج بها لا.","link":"https://binbaz.org.sa/fatwas/20871/حكم-اخذ-المصحف-الموقوف-خارج-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0666هل يجوز أخذ المصاحف الموقوفة في بيت الله خارج المسجد لأجل القراءة؟ ابن باز.mp3","categories":["الوقف"]},{"id":2124,"question":"كثير من أهل السّبالات من كبار السن يُسَبِّلون البيوت –يوقفون البيوت في الوصايا- ويترضى الأبناء في حال الحياة، فهل يجوز لهم؟","title":"حكم وَقْف البيوت وتَسْبِيلُها","answer":"الجواب:\nلهم وقف البيوت إذا نجَّزوا ولا بأس، أمَّا إذا علَّقوا بالموت فلا يكون لهم إلا الثلث.\nس: أقصد إذا كان الورثةُ مُتراضين في حال حياته؟\nج: حتى لو ما رضوا، فلا بأس أن يُوقِف ما شاء من ملكه، وليس رضاهم شرطًا في ذلك، وإنما هو شرط في الوصية، ففي الوصية له الثلث، إلا أن يرغبوا في الزيادة، أمَّا إذا كان صحيحًا ووقف وقال: هذا البيت وقفٌ لي، أو أوقفه لغيره وهو صحيح؛ فإنه يمضي كله، ولو ما رضي الورثة.\nس: لو أوقف كلَّ ماله هل يجوز له؟\nج: نعم يجوز، لكن الأفضل له ألا يفعل ذلك، مثلما قال النبيُّ ﷺ لسعدٍ ولأبي لبابة، كونه يخلي البعض للورثة، قال النبي: أمسك عليك بعضَ مالك فهو خيرٌ لك، فكونه يترك بعضَ المال أفضل؛ حتى لا يحتاج.","link":"https://binbaz.org.sa/fatwas/22242/حكم-وقف-البيوت-وتسبيلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وقف البيوت وتسبيلها.mp3","categories":["الوقف"]},{"id":2827,"question":"مَنْ كان له صدقة جارية أوقفها ثم رأى الورثة من بعد موته أن يجعلوها في مجال آخر، هل لهم ذلك؟","title":"هل للورثة حق تغيير مجال الصدقة الجارية؟","answer":"الجواب: ليس لهم ذلك إلا بمراجعة ولي الأمر، المحكمة؛ إنْ كان فيها مصلحة تنظر في الأمر.","link":"https://binbaz.org.sa/fatwas/22976/هل-للورثة-حق-تغيير-مجال-الصدقة-الجارية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للورثة حق تغيير مجال الصدقة الجارية.mp3","categories":["الوقف"]},{"id":4896,"question":"بالنسبة لبيع الوقف؟","title":"ما ضوابط الوقف؟ وهل يجوز بيعه؟","answer":"إذا تعطلت منافعه يُباع. وقال بعض أهل العلم: إذا كان البيع بما هو أصلح؛ جاز، من باب نفع الواقف؛ فإذا كان في محل ما هو مناسب أو قلت ثمرته فباعه لما هو أصلح؛ فلا بأس، ولكن المشهور عند العلماء: إذا تعطلت منافعه أو شبه متعطل، مثل حارة انتقل أهلها والبيت ما عاد يسوي شيئًا، أجرته قليلة؛ يباع ويلتمس بيت آخر في محل مرغوب.\nس: إذا أوقف عمارة وقال إيجارها لكم ولكن إذا مت واحتاجها أولادي أخذوها؟\nج: هذا ما هو بوقف، هذا تبرع بالأجرة.\nس: الكتب هل تعتبر من العلم؟\nج: نعم، وقف الكتب من العلم.\n س: لكن أوقفها في بيته لبيته؟\nج: ما تُسمَّى وقفًا إلا إذا أوقفها، أما إذا أوقفها على الورثة -لعياله ميراثًا- ما تُسمَّى: وقفًا، لكن إذا انتُفِعَ بها يُرجى له الخير.\nس: إذا أوقف ماله كلَّه؟\nج: إذا كان صحيحًا الأفضل يخلي له بعض الشيء، مثلما قال لكعب بن مالك: أمسك عليك بعض مالك، أمسك يعني: خلِّي لك شيئًا يقوم به حالك وأوقف ما تيسر؛ حتى لا يضطر، يكون فقيرًا يشحذ الناس، يخلي له بعض الشيء.","link":"https://binbaz.org.sa/fatwas/25411/ما-ضوابط-الوقف-وهل-يجوز-بيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز بيع الوقف.mp3","categories":["الوقف"]},{"id":5486,"question":"هل يجوز أخذ المصحف من المسجد المكتوب عليه: \"وقف لله تعالى\" للتلاوة في البيت؟","title":"ما حكم أخذ مصحف المسجد للتلاوة في البيت؟","answer":"الجواب: لا يأخذ المصحف، أوقاف المسجد تبقى للمسجد، مصاحف المسجد تبقى في المسجد، يقرأه في المسجد، ولا يأخذه من المسجد.[1]","link":"https://binbaz.org.sa/fatwas/31390/ما-حكم-اخذ-مصحف-المسجد-للتلاوة-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sharh_alosol 002.mp3","categories":["الوقف"]},{"id":6570,"question":"لي خال قد توفي، وأوقف أرضًا زراعية في حياته على تشييد بئر، ومسجد، علمًا بأنه كانت بقرية، وهاجرنا إلى غيرها؟الشيخ: أعد.الطالب: لي خال توفي، وأوقف أرضًا زراعية في حياته على تشييد بئر، ومسجد، مع العلم أنه كانت بقرية، وهجرنا هذه القرية إلى غيرها، وصار المسجد لا يصلى فيه، والبئر بعيد عنها، فهل تباع الأرض الزراعية، ويُقَوم ثمنها في بناء المسجد مكاننا اليوم؟","title":"حكم بيع الوقف إذا تعطلت منافعه","answer":"الجواب:  إذا تعطل المسجد، أو البئر في محل من المحلات، إذا وقف إنسان بئرًا، أو عمّر مسجدًا، ثم انتقلت القرية، وتعطل المسجد، وتعطلت البئر، فإنهما يباعان إن وجد من يشتريهما، إن وجد من يشتري المسجد، أو يشتري البئر، يباعان، ويصرف ثمنهما في القرية الثانية التي انتقلوا إليها؛ حتى ينتفعوا في هذا الأمر، يبنى لهم مسجد هناك، ويحفر لهم بئر هناك، بدلًا من البئر، والمسجد في القرية التي انتقلوا عنها، ولا بقي فيها أحد ينتفع بالمسجد، ولا بالبئر؛ لأن المقصود النفع، والفائدة.  فإذا انتقل أهل القرية، وصارت القرية خالية، ووجد من يشتري المسجد، أو يشتري البئر بأمر ما، أو بفائدة ما، فإنهما يباعان عليه، ويصرف ثمنهما في مسجد في القرية الأخرى، وفي بئر لهم أيضًا، حتى يتم انتفاعهم بذلك.","link":"https://binbaz.org.sa/fatwas/2410/حكم-بيع-الوقف-اذا-تعطلت-منافعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_937.mp3","categories":["الوقف"]},{"id":6774,"question":"عمي أوصى بثلث ماله وقفًا لله تعالى، ولم يحدد هذا الوقف، فهل يجوز إرسال بعض هذا المال إلى المتضررين بالمجاعة في السودان، وغيره، مع عدم معرفة هل تصل إلى المسلمين، أو غير المسلمين؟","title":"حكم صرف الوقف لمتضرري المجاعة والتصدق على الكفار","answer":"الجواب: نعم، نعم، إذا كان الوقف في وجوه البر، وأعمال الخير، أو قال وقفًا لله، أو في طُعِمْ كما يقول بعض البادية، أو في وجوه البر، أو في وجوه الخير، أو قال وقفًا لله، وسكت؛ يصرف في وجوه الخير، ولا مانع أن يعطى منه المتضررون من السودان، وغير السودان، حتى ولو كان فيهم غير المسلمين ممن لهم أمان لغير المسلمين؛ لأنهم تجوز فيهم صدقة التطوع، الكفار يعطون من صدقة التطوع، كما قال الله -جل وعلا-: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8] فأخبر سبحانه أنه لا ينهانا أن نبرهم ونقسط إليهم إذا كانوا ليسوا حربا لنا. وهكذا ثبت في الصحيح عن أسماء بنت أبي بكر -رضي الله تعالى عنهما- أن أمها وهي مشركة جاءت إليها في المدينة -في وقت الهدنة- تطلبها مالًا، فقالت أسماء: يا رسول الله، ماذا ترى في ذلك؟ فقال: صليها فأمرها أن تصل أمها وهي مشركة.  فالمقصود: أن صلة المشرك بالمال المتطوع به إذا كان ليس حربًا لنا -كالمستأمن والمعاهد والذمي ونحو ذلك- لا بأس، إنما الذي ينهى عنه، ولا يجوز وصله إذا كان حربًا لنا، إذا كان بيننا وبينهم الحرب، وعدم الأمان، وعدم العهد؛ فهذا هو الذي لا يعطى شيئًا، لا قليلًا ولا كثيرًا.  فأما الصدقة على الفقراء، والمساكين، والذين لا حرب بيننا وبينهم، فلا حرج في ذلك من غير الزكاة، أما الزكاة فلا تصرف إلا للمسلمين عند جمهور أهل العلم.","link":"https://binbaz.org.sa/fatwas/2653/حكم-صرف-الوقف-لمتضرري-المجاعة-والتصدق-على-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1149.mp3","categories":["الوقف","صدقة التطوع"]},{"id":6885,"question":"ما رأيكم -جزاكم الله- في ثلث مال والدي المتوفي، المسمى بالسبيل، هل يجوز لي آكل منه أنا وعيالي، مع العلم أنه ماشية، وعيالي يربونه، ويتعبون فيه؟","title":"حكم الأكل مما أوقف الوالد السبيل","answer":"الجواب: إذا أوصى والدك بالثلث في أعمال البر .. كما هي عادة البادية، فإنك تأكل منه أنت وأهلك إذا كنت محتاجًا إليه، تأكل منه بالمعروف، في ملبسك، ومأكلك، وضيفك، ونحو ذلك بالمعروف. وكذلك إذا كان أولادك يخدمون هذا الثلث، ويتعبون فيه؛ لك أنت وأولادك الأكل بالمعروف. وإذا أغناك الله عنه، ولم يكن لك فيه حاجة؛ فالأولى أن توفره لأعمال الخير، لمساعدة الفقراء، والمساكين، وللمساعدة في أعمال الخير، كبناء المساجد، وقضاء الدين عن المدينين، ونحو ذلك. وإذا احتجت إلى ذلك؛ فأنت أولى من غيرك في حاجتك خاصة، من غير أن تتخذ منه أموالًا، ومساكن، ونحو ذلك، بل تأخذ حاجتك، تأكل حاجتك فقط، وحاجة أهل بيتك، وإذا جعلت فيه من يقوم عليه بالأجرة المعتادة من أولادك، أو غيرهم، يقوموا عليه إذا كان غنمًا، أو إبلًا؛ فلا بأس أن تعطيه الأجرة المعتادة.","link":"https://binbaz.org.sa/fatwas/2775/حكم-الاكل-مما-اوقف-الوالد-السبيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1267.mp3","categories":["الوقف","صدقة التطوع"]},{"id":7713,"question":"أيضاً يقول: إنني حفرت بئر، ونشرب منه نحن والجيران، وبنيته من حصى المقبرة، وعمري كان خمسة عشر سنة، هل علي في هذا الحال ذنب أم كيف أعمل، جزاكم الله ...... ؟ الشيخ: أعد أعد. يقول: إنني حفرت بئراً، ونشرب منه نحن والجيران، وبنيته من حصى المقبرة، وعمري كان خمسة عشر سنة، هل علي في هذه الحال ذنب أم كيف أعمل، جزاكم الله خير الجزاء، والبئر لا زال موجوداً في سوريا؟","title":"حكم استعمال أحجار المقبرة في بناء بئر","answer":"الجواب: إذا كان الحجر معداً للمقبرة معداً للقبور؛ لأنهم يعني يردمون بها اللحد فلا بأس، إذا كان معد للمقبرة يحضر بدلاً منه، يعني يشتري بدلاً منه، بدل الذي جاء في البئر ويحطه للمقبرة، إذا كان الحجر هذا مملوكاً للمقبرة، يعني مسبل للمقبرة وأخذ منه للبئر والبئر ما هي من مصلحة المقبرة، أما إن كان من مصلحة المقبرة يعني يغسلون منه الموتى ويستفيدوا منها في تغسيل الموتى هذا من عمل مصلحة المقابر لا بأس، أما إذا كانت البئر لا، لا تعلق لها بالموتى ولا بالمقبرة نعم. لأبناء السبيل مثلاً، فهذا الحجر الذي أخذه من أحجار المقبرة يلزمه أن يبدله، يعني: يشتري بداله، الذي حطه في البير يشتري بدلاً منه، ويحطه مع أحجار المقبرة لحاجة المقبرة. \nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4912/حكم-استعمال-احجار-المقبرة-في-بناء-بىر ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_030/03007.mp3","categories":["الوقف"]},{"id":9520,"question":"هذا سؤال من المستمع محمد أحمد على زعبان من تهامة عسير بلاد رجال ألمع يقول: كان يوجد لدي قطعة أرض وقد تبرعت بها مقبرة للقرية المجاورة ولا أريد منها إلا وجه الله عز وجل، ولكن حدث عدة أمور جعلتني أحتار فيها، فقد استأذى منها صاحب الأرض التي تحد أرضي التي تبرعت بها، حيث أن مياه المقبرة من الأمطار وغيرها تسيل على أرضه وهي تقع في الجانب الأعلى لمزرعة الأخ المتضرر، كما أن موقعها غير صالح أن يكون مقبرة ولم أنتبه لذلك إلا بعد أن تبرعت بها، حيث أنها تقع في ساحة القرية وتمر معها المواشي، وحتى لو استطعنا أن نجعل للمواشي طريقاً أخرى فلا نستطيع أن نضمن سلامتها من عثور هذه المواشي بين لحظة وأخرى، لذا أسأل فضيلتكم هل يجوز لي أن أستعيدها وأبدلها بقطعة أخرى من مالي تكون مقبرة وهي في مكان أحسن، أم أبيعها وأتصدق بثمنها، أفيدونا جزاكم الله خير الجزاء ؟","title":"حكم استبدال أو بيع أرض وقفت مقبرة","answer":"الجواب: إذا كانت الأرض المذكورة لم يقبر فيها حتى الآن و تيسر ما هو أحسن منها فإنك تبدلها، إذا تيسر أن تبدلها بخير منها أو بمثلها في مكان أسلم من هذا المكان لا يضر جارها ولا يسبب امتهان المواشي لها فإنك تجعلها في مكان آخر، تعين أرضاً أخرى مناسبة خيراً منها وتستعيد هذه الأرض، أو تبيعها وتشتري بها أرضاً مناسبة تجعلها مقبرة للبلد في محل مناسب، أما إن كانت قد تم القبر فيها والدفن فيها فإنها تسور ويمنع نزول سيلها ومطر مائها على جارها يجعل سور بينه و بينها حتى لا ينضر بها وتسور على الأموات الذين بها والحمد لله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7683/حكم-استبدال-او-بيع-ارض-وقفت-مقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_244/24402.mp3","categories":["الوقف"]},{"id":9594,"question":"الرسالة التالية وصلت من إخوة سودانيين مقيمين بالمملكة يقولون في سؤالهم الأول:هل يمكن أن يشيد الإنسان صدقة جارية ويهبها لأحد الأصدقاء أو الأقرباء غير الأب والأم، وهل يمكن أن يصل أجرها إليه، أفيدونا أفادكم الله؟","title":"حكم تشييد صدقة جارية وهبتها","answer":"الجواب: قول السائل هل يمكن أن يشيد صدقة جارية معنى التشييد لم أفهمه، فإن كان المراد بالتشييد ............. ويحدث أرضًا صدقة جارية أو إنارة تكون صدقة جارية أو دكان يعني حانوت يكون صدقة جارية فلا بأس يسبله ويجعل غلته لأبيه أو أمه أو أقاربه تنفعهم الصدقة تنفع الميت والحي جميعًا، أو يجعل غلته في إصلاح المساجد أو في مواساة الفقراء والمحاويج أو في قضاء دين المديونين أو في بناء أربطة للفقراء وما أشبه ذلك، هذه يقال لها: صدقة جارية، ويقال لها: وقف، ويقال لها: إسبال ويقال لها ....... قال النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له.\nأما إن كان أراد بالتشييد الإخراج ، يعني يريد أن يخرج مالًا من ماله ويخرج نقود أو طعام أو ملابس من ماله يتصدق بها على بعض أصدقائه أو على بعض أقربائه أو على بعض جيرانه المحتاجين أو على غيرهم فكذلك لا بأس بهذا والأجر يلحق، الأجر يلحق الميت والحي إذا أخلصوها لله والتقرب إلى الله بذلك فإنه ينفعه ما أخرجه من ..... أو من ملابس أو أطعمة أو لحوم إذا أعطاها بعض الفقراء أو بعض الأصدقاء للتقرب إلى الله أو لأنه فقير أو ما أشبه ذلك من هذه الأسباب الشرعية فكل هذا ينفع الميت والحي.","link":"https://binbaz.org.sa/fatwas/7760/حكم-تشييد-صدقة-جارية-وهبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19305.mp3","categories":["الوقف","الهبة والعطية"]},{"id":9845,"question":"تقول أيضاً: لنا قريب يقدم لنا بعض الحاجات المنزلية البسيطة، وهذه الحاجات مما اعتاد الناس أن يبيعوها، فقدمنا له نقوداً فلم يأخذها واعتبر أن هذه الحاجة هدية، وبعد مدة استعملنا هذه الحاجات تبين لنا أنه قد سرقها من شركة أجنبية يعمل حارساً عندها، فما حكم استعمالنا لهذه الحاجة بعد معرفتنا أنها مسروقة؟","title":"حكم استعمال الهدية إذا ثبت أنها مسروقة","answer":"الجواب: متى علمتم أن هذه الحاجات مسروقة، فالواجب عليك ردها إلى أصحابها؛ لأن هذا منكر وإنكار المنكر واجب، فإذا علمتم أنها مسروقة فردوها إلى أهلها، وأخبروه أن هذا لا يجوز له، وأن الواجب عليه أداء الأمانة مع الشركة ومع غير الشركة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/8013/حكم-استعمال-الهدية-اذا-ثبت-انها-مسروقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26205.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10033,"question":"يقول: قمت بإحضار بعض الناس لكي يعملوا في إحدى دول الخليج وأخذت منهم بعض النقود برضاهم، فهل يحق لي ذلك وإن كان غير ذلك فماذا أفعل؟","title":"حكم أخذ المال عن الشفاعة في المنافع","answer":"الجواب: إذا كنت اتفقت معهم على مال معلوم من بلادهم حتى توصلهم إلى الخليج وتقوم بما يجب من قيمة التذاكر وغير ذلك، هذا شيء لا حرج فيه، لأنك أديت عنهم مالاً حتى توصلهم إلى إحدى دول الخليج بسبب خدمتك لهم، وسعيك لهم في إيصالهم إلى دول الخليج حتى يعملوا هناك، أما إن كانت الأموال التي أخذتها من أجل الشفاعة لهم في أن يعملوا عند فلان أو عند فلان والنفقة على حسابهم لكن أعطوك المال لأجل الشفاعة اللي عند فلان أو فلان حتى يستخدمهم فلا ينبغي لك أن تأخذ المال، في الحديث: من شفع لأخيه شفاعة فأهدى له هدية فقد أتى باباً عظيماً من أبواب الربا فلا تأخذ عن شفاعتك مالاً، أما إذا كنت خدمتهم في شيء أعطوك المال عن خدمة أخذت لهم الجوازات تعبت لهم في الإقامة عملت أعمالاً كفيتهم إياها وأعطوك المال لخدمتك فقط، فلا حرج فلا نعلم حرجاً في ذلك في مقابل الخدمة التي خدمتهم إياها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8198/حكم-اخذ-المال-عن-الشفاعة-في-المنافع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30102.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10534,"question":"تقول في الفقرة الأخيرة سماحة الشيخ: هل يجوز لنا أن نأكل مما يهديه لنا هذا الرجل من أكل وخضروات وغيره أم لا؟","title":"حكم قبول الهدية ممن يجمع الصلوات ويترك الجماعة","answer":"الجواب: الهدية لها شأن آخر، إذا كان مكسبه طيب لا بأس، الهدية تقبل حتى من الكافر إذا لم يكن هناك موجب لردها، الهدية أمرها أوسع، لكن إذا أراد ردها هجرًا له وتعزيرًا له من باب التنبيه على خطئه فإذا رد هديته وهجره حتى يتوب يكون هذا أصلح من باب التأديب، ومن باب الحث على إقام الصلاة وأدائها، فإذا لم يقبل هديته ولم يزره وهجره فهذا مشروع إذا كان فيه مصلحة، أما إذا كان قبولها والمجيء إليه أقرب إلى الصلاح وإلى أن يستفيد فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8709/حكم-قبول-الهدية-ممن-يجمع-الصلوات-ويترك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28406.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10602,"question":"المستمع عبيد بن حسين الإبراهيم سوري مقيم في عرعر بعث برسالة مطولة بعض الشيء يقول فيها: توفي ابن خالتي وقامت أمه بالتصدق لولدها، حيث أعطتني بقرة بصفة وقف لابنها أستفيد من لبنها على أن أطعم تلك البقرة وأعتني بها، وشاء الله أن البقرة ماتت حيث نطحت فذبحتها وبعت لحمها بمبلغ سبعة آلاف ليرة سوري، وصرفت تلك الفلوس حيث أنني محتاج لها، سؤالي: هل أشتري بقرة بدلاً منها وأعطيها للمتوفى كصدقة، أو أترك من بقرتي حيث أن لدي الآن بقرة أخرى أفيدوني جزاكم الله خيراً؟","title":"حكم من وضع عنده وقف فباعه مضطراً","answer":"الجواب: نعم، الواجب عليك أن تشتري بقرة مثلها حسب الطاقة، بالفلوس التي حصلت لك حين بعت البقرة بعد الذبح تصرفها في بقرة أخرى، تكون وقفاً وصدقة بدل التي ذبحت، وإذا كان عندك بقرة تناسب وعرضتها على اثنين من أهل المعرفة والخير ورأيا أنها مناسبة فلا بأس بالقيمة التي عندك، تكون وقفاً بدل البقرة التي ذبحت، وإذا اشتريت من غيرك بالسبعة الآلاف التي عندك بقرة أو زدت عليها من نفسك فهذا أحوط لك وأبعد عن التهمة، ويكون حكم البقرة الجديدة كالبقرة القديمة. نعم.","link":"https://binbaz.org.sa/fatwas/8788/حكم-من-وضع-عنده-وقف-فباعه-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32615.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10611,"question":"المستمع عبيد بن حسين الإبراهيم سوري مقيم في عرعر بعث برسالة مطولة بعض الشيء يقول فيها: توفي ابن خالتي وقامت أمه بالتصدق لولدها، حيث أعطتني بقرة بصفة وقف لابنها أستفيد من لبنها على أن أطعم تلك البقرة وأعتني بها، وشاء الله أن البقرة ماتت حيث نطحت فذبحتها وبعت لحمها بمبلغ سبعة آلاف ليرة سوري، وصرفت تلك الفلوس حيث أنني محتاج لها، سؤالي: هل أشتري بقرة بدلاً منها وأعطيها للمتوفى كصدقة، أو أترك من بقرتي حيث أن لدي الآن بقرة أخرى أفيدوني جزاكم الله خيراً؟","title":"حكم من وضع عنده وقف فباعه مضطراً","answer":"الجواب: نعم، الواجب عليك أن تشتري بقرة مثلها حسب الطاقة، بالفلوس التي حصلت لك حين بعت البقرة بعد الذبح تصرفها في بقرة أخرى، تكون وقفاً وصدقة بدل التي ذبحت، وإذا كان عندك بقرة تناسب وعرضتها على اثنين من أهل المعرفة والخير ورأيا أنها مناسبة فلا بأس بالقيمة التي عندك، تكون وقفاً بدل البقرة التي ذبحت، وإذا اشتريت من غيرك بالسبعة الآلاف التي عندك بقرة أو زدت عليها من نفسك فهذا أحوط لك وأبعد عن التهمة، ويكون حكم البقرة الجديدة كالبقرة القديمة. نعم.","link":"https://binbaz.org.sa/fatwas/8788/حكم-من-وضع-عنده-وقف-فباعه-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32615.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11279,"question":"في أحد أسئلته يقول: شخص له ثلاث زوجات، كل واحدة منهن لها أولاد ذكور وإناث وتختلف عن الزوجة الأخرى من جهة عدد الذكور والإناث، ويرغب الزوج قسمة العقارات عليهن بحيث يعطي كل واحدة منهن مسكنََا لها ولأولادها الذكور والإناث، علمًا بأن المساكن تختلف بعضها عن بعض من جهة القيمة والمساحة، فهل هذه القسمة مطابقة للشرع أم كيف توجهونه؟ جزاكم الله خيرًا.","title":"حكم من قسم بين أولاده المساكن مع اختلاف قيمتها","answer":"الجواب:  إن كانت القسمة للسكن فقط والعقار باقي على ملكه بحيث يقدر عليه بعد موته ويرثونه، هذا لا حرج يجتهد في التوزيع بينهم وفي إسكانهم والإنفاق عليهم، والعقار على ملكه يبقى على ملكه، وإذا مات حكمه حكم بقية العقار وإرث بين الجميع فلا بأس. أما إذا كان المقصود تمليكه فلابد من المساواة والعدل، يعطي الزوجات على السواء ويعطي الأولاد على السواء للذكر مثل حظ الأنثيين، يعطي الذكر مثل الأنثى مرتين، وكل زوجة يساويها بالأخرى حتى يعدل بينهن لأن الرسول ﷺ يقول: اتقوا الله واعدلوا بين أولادكم ويقول ﷺ: من كانت له زوجتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالحاصل: أن عليه العدل حسب الطاقة في زوجاته وفي أولاده إذا كان عطاء تمليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9466/حكم-من-قسم-بين-اولاده-المساكن-مع-اختلاف-قيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37517.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11584,"question":"تسأل سماحتكم -جزاكم الله خيرًا- عن صديقة لها متوفىً زوجها تقول: إنها أحيانًا تأخذ منها بعض المال، ولكن تفكر في بعض الأوقات وتقول: أرجو أن لا أكون قد أخذت هذا المال بغير حقه؛ لأنه من مال أيتام، فبماذا توجهونها وذلكم الحال؟ جزاكم الله خيرًا.","title":"حكم أخذ المال من امرأة متوفى عنها زوجها","answer":"الجواب:  إذا كنت لا تعلمين؛ فلا حرج عليك، وعليك حسن الظن، والحذر من الوساوس، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9767/حكم-اخذ-المال-من-امراة-متوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38613.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11597,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ن. م) تقول: يوجد عندي خماخم ذهب قد اشتريتها هدية لشغالة كانت عندي سابقًا، وعند سفرها نسيتها عندي، هل تنصحونني بإعطائها لخدامة أخرى، أم أتصرف فيها تصرفًا آخر؛ لأني أخشى إذا بعثتها إليها ألا تصل؟","title":"حكم من أهدى هدية ونسيها المهدى إليه عنده","answer":"الجواب:  الواجب بعثها إليها، إذا كنت أعطيته إياها، وتملكتها منك، ولكن نسيتها فهي ... كسائر مالها، الواجب عليك إيصالها إليها بالطريقة الممكنة، وليس لك التصرف فيها بإعطائها خدامة أخرى ولا غيرها، الواجب إيصالها إلى الخدامة التي أعطيتها إياها، ولا ترجعي في هبتك؛ يقول النبي ﷺ: الراجع في هبته كالراجع في قيئه. فالواجب إيصالها إليها بالطريقة الممكنة، أما إذا عجزت عن إيصالها إليها؛ فإنك تتصدقي بها عنها، إذا لم يتيسر إيصالها إليها؛ فإنه يتصدق بها عنها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9788/حكم-من-اهدى-هدية-ونسيها-المهدى-اليه-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38714.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11599,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ن. م) تقول: يوجد عندي خماخم ذهب قد اشتريتها هدية لشغالة كانت عندي سابقًا، وعند سفرها نسيتها عندي، هل تنصحونني بإعطائها لخدامة أخرى، أم أتصرف فيها تصرفًا آخر؛ لأني أخشى إذا بعثتها إليها ألا تصل؟","title":"حكم من أهدى هدية ونسيها المهدى إليه عنده","answer":"الجواب:  الواجب بعثها إليها، إذا كنت أعطيته إياها، وتملكتها منك، ولكن نسيتها فهي ... كسائر مالها، الواجب عليك إيصالها إليها بالطريقة الممكنة، وليس لك التصرف فيها بإعطائها خدامة أخرى ولا غيرها، الواجب إيصالها إلى الخدامة التي أعطيتها إياها، ولا ترجعي في هبتك؛ يقول النبي ﷺ: الراجع في هبته كالراجع في قيئه. فالواجب إيصالها إليها بالطريقة الممكنة، أما إذا عجزت عن إيصالها إليها؛ فإنك تتصدقي بها عنها، إذا لم يتيسر إيصالها إليها؛ فإنه يتصدق بها عنها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9788/حكم-من-اهدى-هدية-ونسيها-المهدى-اليه-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38714.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11640,"question":"امرأة توفيت سماحة الشيخ، وتركت قطعة أرض لمن يقرأ لها القرآن بعد وفاتها، فكيف التصرف في تلكم الأرض؟ ولا سيما وقد سمعنا أن قراءة القرآن، وإهداء ثوابها إلى الموتى غير جائزة، وهذا السؤال من المستمع: عيسى محمد سالم.","title":"حكم الوقف لقراءة القرآن على الواقف بعد موته","answer":"الجواب:  نعم غير مشروع قراءة القرآن للأموات، ولكن هذه الأرض تصرف غلتها في جماعة معلمي القرآن، تصرف غلتها للذين يعلمون القرآن، ولها أجرها العظيم، تعينهم.. في جماعة القرآن في البلد، أو في أي بلد، تصرف الغلة للقائمين بتعليم القرآن، حتى يستعينوا بها في أجور المدرسين، أو شراء الكتب، ونحو ذلك، أما أن يقرأ القرآن للميتة، لا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9831/حكم-الوقف-لقراءة-القران-على-الواقف-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38918.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12556,"question":"رسالة وصلت إلى البرنامج من المستمع (م. ص. ع) يقول في رسالته: دخلت أحد المساجد ومعي مصحف، ورأيت في المسجد مصاحف ذات طباعة واضحة، وقمت باستبدال مصحفي بواحد من تلك المصاحف الموجودة في المسجد، هل يحق لي ذلك، أم لا؟","title":"حكم استبدال مصحف أوقف على مسجد بمصحف آخر","answer":"الجواب:  ليس لأحد أن يأخذ من أوقاف المسجد شيئًا، لا من المصاحف، ولا من غيرها، إلا إذا كانت موضوعة للتوزيع، إذا كان وضعها الواضع للتوزيع؛ فلا بأس بذلك، إذا قال له الإمام أو المؤذن: هذه للتوزيع؛ فلا بأس، أما إذا كان وضعت لينتفع بها المصلون، والقراء في المسجد؛ فليس لأحد أن يأخذ منها شيئًا، ولا أن يضع بدلها ما هو دونها، نعم. المقدم: نذكر التعليل لو تكرمتم؟ الشيخ: لأنها وقف، لأنها وقف على القراء في المسجد. المقدم: هذه ناحية. الشيخ: ولأن وجود ما هو أصلح ينبغي أن يبقى للقارئ الذي أراده الموقف، فلا يأخذ الطيب، ويدع ما هو دونه، يبقى الطيب لأهل المسجد. المقدم: وحتى لا يخلو المسجد. الشيخ: وكذلك هذا منه حتى لا يخلو من المصاحف أيضًا، لكن قد يقول: أنا وضعت مصحفي بدل المصحف. المقدم: لا، قصدي حتى لا يخلو المسجد من المصاحف ذات الطباعة الجيدة. الشيخ: نعم هذا مطلوب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10756/حكم-استبدال-مصحف-اوقف-على-مسجد-بمصحف-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41002.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12679,"question":"المستمع: أحمد محمد مصري مقيم في جدة بعث برسالة مطولة بعض الشيء يقول فيها: لي أخت تزوجت من رجل، ثم طلقت منه بعد أن أنجبت منه بنتين، وتزوجت برجل آخر وهي تعمل، ويدخل راتبها البيت، وقد تمكنت من بناء شقة هي وأختها، وزوجها يعلم بذلك، وبعد أن انتهت من بناء هذه الشقة، فإن زوجها يطلب منها أن تكتب ما تمتلكه من هذه الشقة لابنتها التي أنجبتها منه، وحرمان ابنتيها من زوجها الأول، مع العلم أنها بنت هذه الشقة من مالها الذي كانت تعمل وتحصل عليه، وجهونا حول هذا الموضوع، جزاكم الله خيرًا؟","title":"حكم تخصيص أحد الأبناء بهبة دون غيره","answer":"الجواب:  لا يجوز لهذا الرجل أن يلزمها بذلك، ولا أن يأمرها بذلك، ولا يجوز لها أن تطيعه في ذلك؛ لأن هذا من الظلم، والرسول -عليه الصلاة والسلام- يقول: اتقوا الله، و اعدلوا بين أولادكم. فالواجب عليها أن تعدل بين بناتها، وأن يكن سواء في وصيتها وعطيتها، وليس لها أن تحيف فتزيد واحدة على أخرى، وليس له أن يأمرها بذلك، بل هذا حرام عليه، وهو من الإعانة على الإثم والعدوان، ومن الأمر بالظلم فلا يجوز، فليس لها طاعته في هذا الأمر، بل هذه معصية، والرسول  يقول: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق ولو أوصت، أو أعطت البنت التي هي بنته دون البنتين؛ فالعطية باطلة، والوصية باطلة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10889/حكم-تخصيص-احد-الابناء-بهبة-دون-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41708.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12808,"question":"المستمع محمد علي محمد عسيري بعث برسالة مطولة ملخص ما فيها طلب إيضاح أحكام الوقف، وهل يجوز بيعه إذا تعطلت منافعه، ونقله إلى مصالح أخرى، جزاكم الله خيرًا؟","title":"حكم بيع الوقف عند تعطل منافعه","answer":"الجواب:  نعم الوقف لا يباع ولا يوهب ولا يورث كما قاله النبي ﷺ: تصدق بأصلها قال لعمر تصدق بأصلها، لا يباع ولا يوهب، ولكن ينفق وثمره فالوقف لا يباع ولا يوهب ولا يورث، بل يبقى حبسًا تنفق غلته وثمرته في الوجوه التي عين، وجوه الخير التي عينها الواقف، وإذا تعطلت منافعه؛ فإنه يباع، ولا يترك، يباع ويرجع ثمنه فيما هو أصلح منه إذا تعطلت المنافع، لكن من طريق المحكمة، إذا كانت البلاد فيها محكمة؛ تراجع المحكمة حتى تضبط الأمور. أما إذا كان في بلاد ما فيها محكمة؛ فالولي يقوم بذلك، وكيل الوقف يبيعه، ويشتري به ما هو أصلح، إن كان بيتًا؛ اشترى بيتًا أصلح، ولو صغيرًا، أو دكانًا ولو صغيرًا حسب التيسير، يجتهد في تحصيل ما هو أصلح ولا يترك معطلًا؛ لأن هذا من إضاعة المال، والرسول ﷺ نهى عن إضاعة المال، فإذا تعطلت منافع الوقف؛ فإنه يباع، ويشترى به ما هو أصلح من بيت، أو دكان، أو مزرعة، أو نحو ذلك، تنفق ثمرته في الوقف الذي بيع ثمرته مثلما في غلة الوقف الذي بيع حسب الوصية، وحسب وثيقة الوقف. أما إذا كان في بلد فيها محاكم شرعية؛ فإن الوكيل يراجع المحاكم، ويرى ما توجهه إليه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11022/حكم-بيع-الوقف-عند-تعطل-منافعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46213.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12920,"question":"من المستمع حسن سعيد محمد القعيدي من اليمن حضرموت رسالة ضمنها أكثر من سؤال، في سؤال له طويل ملخصه يقول: إذا انقطعت منافع الوقف فهل يباع لينتفع بثمنه في جهة أخرى؟","title":"حكم بيع الوقف إذا تعطلت منافعه","answer":"الجواب:  نعم، إذا تعطلت منافع الوقف؛ يباع ويشترى به ما هو أصلح منه، فإذا كان بيتًا تعطل، أو دكانًا تعطل؛ يباع، ويشترى به بيت أصغر، أو دكان أصغر ينتفع به، أو أرضًا تعطلت من الزراعة، ما رغب فيها الناس؛ تباع حتى تتخذ مساكن، ويشترى بها ما هو أصلح منها، أو يعمرها صاحب الوقف بيوتًا للسكن، إذا كان يستطيع ذلك، ولا تعطل؛ لا يترك الوقف عاطلًا؛ لأن هذا من باب إضاعة المال، لا يجوز، بل يجب أن ينظر في أمره، إما بإصلاحه، وتعميره، وإما ببيعه وشراء ما هو أصلح منه، ويكون ذلك بواسطة المحكمة، إذا كان في البلاد محكمة، في بلاد إسلامية فيها محكمة، وإلا يكون ذلك بواسطة أهل الخير، كمركز إسلامي، أو العالم الذي يوثق به في البلد، أو في الأقلية الإسلامية؛ حتى يتعاون مع ناظر الوقف في ذلك. المقصود: أن ناظر الوقف يتعاون مع أهل الخير في ذلك حتى يبرئ ذمته، وحتى يسلم هذا الوقف من التعطل. أما إذا كان في بلد فيها محكمة؛ فإن الناظر يستشير المحكمة، ويسير على ضوء توجيهات المحكمة في البيع، وفي شراء البديل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11135/حكم-بيع-الوقف-اذا-تعطلت-منافعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46905.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12933,"question":"هذه رسالة وصلت من المغرب، من أحد الإخوة المستمعين، يقول في هذا  شخص أهديت له هدية عبارة عن مجوهرات ذهبية،  هل له أن يبيعها، ويستفيد بثمنها؟ أفتونا جزاكم الله خيرًا.","title":"حكم بيع أو إهداء الهدية","answer":"الجواب:  نعم، إذا أهدي لك هدية، وليست رشوة، هدية من أخ محب، أو من قريب ليست في مقابل خيانة ولا .. فلا بأس، تكون مالًا لك تتصرف فيها .. تبيعها .. تمسكها .. تهديها إلى غيرك، لا بأس، أما إن كانت رشوة حتى تميل عن الحق، أو حتى تحكم بالجور، أو حتى تظلم أحدًا؛ فلا يجوز ذلك، إذا كانت هذه الهدية رشوة لك حتى تظلم، أو تخون في قضية عندك، أو أنت قاضي وتحكم بغير الحق، كل هذا منكر. وأما إذا كان هدية لله وفي الله؛ لأنك صديقه؛ لأنك أخوه في الله؛ لأنك قريبه؛ ليس لأي أمر آخر من أمور الخيانات والظلم؛ فلا بأس بذلك، هي مال لك تتصرف فيها، والسنة لك أن تقابله، أن تثيبه على هديته، كان النبي ﷺ يقبل الهدية، ويثيب عليها، يعني: يعطي عليها المقابل، هذا هو الأفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11149/حكم-بيع-او-اهداء-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50108.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12961,"question":"السائل من القصيم يقول: هل إهداء المصحف جائز إذا كان قد أتاني هدية لست بحاجة إليه لوجود آخر عندي، فهل إهداء المصحف جائز؟","title":"حكم إهداء المصحف","answer":"الجواب:  نعم، إلى المسلم تعطيه المسلم، تهديه إلى أحد المسلمين طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11178/حكم-اهداء-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50217.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13073,"question":"هذا السائل حمدي يعمل بالرياض يقول: بأنه يعمل بالمملكة، فهل عند عودتي لبلدي لا بد من أخذ هدايا للأهل والأقارب، علمًا بأن ذلك الموضوع سوف يكلفني الكثير، وهل إذا لم آخذ هدايا أكون قد ارتكبت إثمًا من باب قطيعة الرحم لأهلي، وجهونا في ذلك؟","title":"حكم بذل الهدية","answer":"الجواب:  الهدايا غير واجبة، لا، ما هو بلازم، الهدايا غير واجبة، ولا تكون قاطعًا للرحم إذا ما حملت هدايا، الهدايا باختيارك إن رأيت أن تأخذ هدايا لخواص أقاربك؛ فلا بأس، وإلا ليس بلازم، أنت أعلم بالمصلحة، المهم أن تحفظ المال لحاجة البيت، وحاجتك، وحاجة أهلك، فإذا اشتريت هدية خفيفة للزوجة، أو لأبيك، أو لأمك، أو لإخوانك؛ فلا بأس، وإن شق عليك ذلك؛ فالحمد لله، ما لزوم هدية، المال احفظه لحاجة البيت، لحاجتك، أو لقضاء دينك، أما الهدايا فهي مستحبة عند اليسر .. عند القدرة واليسر إذا أهديت لإخوانك، الرسول ﷺ يقول: تهادوا تحابوا اللهم صل عليه وسلم، فالهدية طيبة مع القدرة، ومع السعة إذا تيسرت من غير تكلف. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11289/حكم-بذل-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50705.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13078,"question":"هذه سائلة تقول في هذا  عندي مبلغ من المال، وأريد أن أجعله وقفًا في سبيل الله  و أي الأعمال أفضل في هذا الوقف، هل هو بناء مسجد، أم غيره أفضل، دلوني يا سماحة الشيخ مأجورين؟","title":"أفضل أنواع الوقف","answer":"الجواب:  إذا كان المال كثيرًا فاجعليه في عقار... في وجوه الخير، بناء المساجد، والصدقة على الفقراء والمساكين، ومساعدة طلبة العلم في طلب العلم، مساعدة من يقوم بعمل شرعي، ويعجز عنه. المقصود: أن يكون في أعمال البر، إذا كان مالًا كثيرًا، يشترى به عقارًا كبيرًا، أو عقارات توقف في أعمال البر، ووجوه الخير، من الصدقة على الفقراء والمساكين .. من مساعدة المجاهدين في سبيل الله .. من بناء المساجد إلى غير هذا من وجوه الخير، الصدقة على الأقارب المحاويج، إلى غير ذلك. أما إن كان قليلًا فاصرفيه في الصدقة على الفقراء إذا كان في أقارب فقراء؛ فأعطيهم إياه، فإن كان ما هناك أحد؛ يصرف في تعمير المساجد، أو في الفقراء في غير البلد إذا كان ما في البلد فقراء بلدك. المقصود: أنه يكون في وجوه البر، لكن إذا كان قليلًا؛ تجعلينه في الفقراء، أو في تعمير المساجد مساهمة، كله طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11295/افضل-انواع-الوقف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50710.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13231,"question":"السائلة من اليمن تقول: لي جارة ملتزمة بشرع الله، والحمد لله، ولكن زوجها شارب للخمر، وهناك شبهة في بيعه للخمر، ما حكم الأكل الذي تهديه لي هذه الجارة، هل أقوم بأكله أم لا، وهل أقبل ما تهديه إلي من هدايا؛ علمًا بأنها تدعوه إلى الله؛ فلا يجيب، وجهونا بذلك؟","title":"حكم قبول الهدايا ممن اختلط ماله بالمال الحرام","answer":"الجواب:  لا حرج في ذلك إذا كان سامحًا لها تهديه، إذا كان سامحًا لها تهديه من ماله؛ فلا بأس؛ لأن المال المختلط يجوز أخذه، والنبي ﷺ أكل من طعام أهل الكتاب، واشترى منهم، وهم يأكلون الربا، ومع هذا اشترى منهم طعامًا، وأكل من طعامهم؛ فدل ذلك على أن المال المختلط الذي فيه ربا، أو فيه ثمن خمر، أو ما أشبه ذلك، وعندهم أموال أخرى حلال لا بأس، الأصل الحل والإباحة حتى تعلم أن هذا المال ربا أو هذا المال من ثمن الخمر، فلا، إذا علمت أن هذا الطعام اشتراه من ثمن الخمر، أو اشتراه من الربا فلا يجوز، وأما إذا لم تعلم؛ فالأصل الإباحة والحل. ولكن هذا الزوج ينبغي لها أن تبتعد عنه مهما أمكن، وإن كان مسلمًا لكن كونه يعتاد شرب الخمر؛ هذه معصية عظيمة، وفسق ظاهر، فكونها تطلب الطلاق منه وتعافه خير لها وأولى لها، وخير لذريتها أيضًا، نسأل الله العافية والسلامة. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11512/حكم-قبول-الهدايا-ممن-اختلط-ماله-بالمال-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52014.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13273,"question":"السائل يقول: هل تقبل هدية من مشرك؟","title":"حكم قبول الهدية من المشرك","answer":"الجواب: هذا فيه تفصيل: إذا كانت الهدية لا تتضمن شرًا على مسلم، لا يتسلط بها الكافر عليه، أو لا يتجرأ بها على المسلمين، ولا يترتب عليها شر؛ فإنه يقبلها المسلم، ويكافئ عليها، يكافئ عليها مثلها، أو أحسن منها، والنبي ﷺ قبل من قوم، ورد على قوم، قبل من مشركين بعض الهدايا، ورد على آخرين، لم يقبل هداياهم. فإذا كان قبولها أصلح، يترتب عليها تأليف قلبه، ومحبته للمسلمين، ويثيب عليها أكثر من المهدى إليه؛ قبلها، فإن كان قبولها يسبب شرًا على المسلمين، أو أن هذا المهدي يتجرأ على المسلمين، أو يؤذيهم، أو يفعل أشياء تضرهم بسبب هذه الهدية، أو المُهدَى إليه هذه الهدية تفضي إلى محبته للكافر المُهدِي، والتعاون معه فيما يضر المسلمين؛ لم يقبلها؛ لئلا تضره؛ لئلا تجره إلى الباطل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11557/حكم-قبول-الهدية-من-المشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50910.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13992,"question":"هذا السائل ناصر إبراهيم من حوطة بني تميم، يقول في هذا  حصل وأن قمت ببيع بيت صغير مبني من الطين، وبعد البيع عثرت الوالدة على وثيقة لهذا البيت ووجد فيها وقف في أضحية من ريعه دون علمي ولم يدخل علي من هذا البيت شيء من إيجاره، والمبلغ المبيوع بهذا البيت هو خمسة آلاف ريال منذ أكثر من عشر سنوات، فهل يسقط البيع شرعًا في هذه الحالة، أم يلزمني نقل الوقف ويبقى في ذمتي سماحة الشيخ؟","title":"حكم من باع شيئًا وتبين أنه وقف","answer":"الجواب: عليك مراجعة المحكمة في إبطال البيع وبقاء الوقف على حاله، وعرض الوثيقة على القاضي والقاضي ينظر في الأمر، فإن لم يتيسر رد البيع فالثمن يجعل في وقف آخر الذي دخل عليك يكون في وقف آخر، يكون في نخلة تقع وقفًا له، يكون في أواني تكون وقفًا له تستعمل ينتفع بها، المقصود: الثمن تجعله في شيء ينفع الميت نخلة أو نخلتين ينتفع بثمرها أو غير ذلك مما ينفع الميت، حسب التيسير. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12407/حكم-من-باع-شيىا-وتبين-انه-وقف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53916.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14108,"question":"هل يجوز أخذ أي كتاب سواء كان قرآن أو أي كتاب آخر كتب عليه وقف، هل يجوز أخذه من المسجد؟","title":"حكم أخذ كتاب أو مصحف موقوف في مسجد","answer":"الجواب: لا يجوز أخذه من المسجد، بل يترك في المسجد لينتفع به من كان في المسجد من القراء، يطالعون فيه يستفيدون منه؛ لأن الواضع الذي وضعه في المسجد أو في مكتبة المسجد قصده نفع الناس، فلا تأخذ المصحف الذي في المسجد ولا الكتاب الذي في المسجد، دعه للقراء في المسجد أو في المكتبة التي في المسجد.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12548/حكم-اخذ-كتاب-او-مصحف-موقوف-في-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48416.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14232,"question":"المستمع (م. م) من قطر بعث يسأل ويقول: هناك بعض أناس يأتون بمصاحف قديمة ويضعونها في المساجد ويستبدلونها بمصاحف جديدة من نفس المسجد فهل هذا جائز؟","title":"حكم استبدال المصاحف من المسجد واستعارتها","answer":"الجواب: ليس لأحد أن يأخذ من مصاحف المسجد شيء، المصاحف التي في المسجد يجب أن تبقى في المساجد وليس لأحد أن يأخذ منها شيئًا أو يبدلها، بل الواجب تركها في المساجد؛ لأن أهلها أرادوا أنها وقف لينتفع بها المسلمون في المسجد، فليس لأحد أن يأخذ منها شيئًا ولا أن يبدلها لا بقديم ولا بجديد.\nالمقدم: هل الاستعارة من المساجد جائزة أو لا؟\nالشيخ: ليس له أن يستعير، أما من المكتبات لا بأس إذا سمح مدير المكتبة والقائم عليها بالإعارة لا بأس، أما ما وضع في المسجد من الكتب أو من المصاحف فلا يستعار بل يطالعه وهو في المسجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12691/حكم-استبدال-المصاحف-من-المسجد-واستعارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48606.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14313,"question":"يسأل أخونا أيضًا ويقول: هل كتابة القرآن الكريم على جدار المساجد جائز؟ أم أنه غير جائز؟","title":"حكم كتابة الآيات القرآنية على جدران المساجد","answer":"الجواب: يكره ذلك؛ لأنه يشوش على المصلين، فالأفضل والأولى أن لا يكتب في جدران المساجد لا القرآن ولا غيره، وقد نص كثير من أهل العلم على ذلك؛ لأن المساجد محل الصلاة ومحل العبادة، فالأفضل أن تكون خالية مما يشوش على المصلين من الكتابات أو النقوش، فلا ينبغي أن يكتب في جدرانها آيات قرآنية ولا غيرها حتى لا يحصل التشويش على المصلي، بل تكون سادة ليس فيها شيء هذا هو المشروع، وأقل الأحوال في الكتابات في المساجد الكراهة لما فيها من شغل المصلين والتشويش عليهم حتى ولو بغير الآيات من الأحاديث أو الأبيات الشعرية أو غير هذا مما قد يكتب، وهكذا النقوش التي قد تشغل المصلي يكره وجودها في المساجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12784/حكم-كتابة-الايات-القرانية-على-جدران-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62202.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":14316,"question":"يسأل أخونا أيضًا ويقول: هل كتابة القرآن الكريم على جدار المساجد جائز؟ أم أنه غير جائز؟","title":"حكم كتابة الآيات القرآنية على جدران المساجد","answer":"الجواب: يكره ذلك؛ لأنه يشوش على المصلين، فالأفضل والأولى أن لا يكتب في جدران المساجد لا القرآن ولا غيره، وقد نص كثير من أهل العلم على ذلك؛ لأن المساجد محل الصلاة ومحل العبادة، فالأفضل أن تكون خالية مما يشوش على المصلين من الكتابات أو النقوش، فلا ينبغي أن يكتب في جدرانها آيات قرآنية ولا غيرها حتى لا يحصل التشويش على المصلي، بل تكون سادة ليس فيها شيء هذا هو المشروع، وأقل الأحوال في الكتابات في المساجد الكراهة لما فيها من شغل المصلين والتشويش عليهم حتى ولو بغير الآيات من الأحاديث أو الأبيات الشعرية أو غير هذا مما قد يكتب، وهكذا النقوش التي قد تشغل المصلي يكره وجودها في المساجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12784/حكم-كتابة-الايات-القرانية-على-جدران-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62202.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":14323,"question":"السائل أبو أحمد يقول: أسأل عن الوقف وما هو الأفضل فيه الصدقة أم الوقف؟","title":"ما الأفضل للمسلم الوقف أم الصدقة؟","answer":"الجواب: هذا فيه تفصيل: قد تكون الصدقة أفضل في حياة الإنسان يقدم الخير لنفسه قبل وفاته، وقد يكون الوقف أفضل إذا كان خلفه من يحسن القيام على الوقف، ويحسن التصرف حتى تكون صدقة جارية له تنفعه.\nوالأحسن أن يجمع بين الأمرين، يتصدق في حياته وينفق ويوقف ما ينفعه بعد وفاته ويجعلها على يد الثقة الذي يظن فيه الخير وأنه ينفذ ما يقول له؛ لأن الرسول ﷺ: أمر عمر أن يوقف، قال -في أرض له في خيبر- تصدق بأصلها لا يباع ولا يوهب ولكن ينفق ثمره وقال: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية أو علم ينتفع به أو ولد صالح يدعو له. فالوقف في وجوه البر وأعمال الخير مطلوب وجيد ونافع، والصدقة في الحياة وتنجيزها نافع أيضًا.\nفالمسلم يجمع هذا وهذا، يتصدق ويحسن في حياته ويبادر بالخير، وإذا وقف وقفًا بعد وفاته يجمع بين الحسنيين، يكون الوقف في وجوه الخير وأعمال البر كعمارة المساجد والصدقة على الفقراء من أقاربه وغيرهم، والمحتاجين من أقاربه وغيرهم والإنفاق في سبيل الله في تعليم العلم.. في توزيع الكتب.. شراء المصاحف وتوزيعها.. إلى غير هذا من وجوه البر، ويكون على يد الثقة من أقاربه أو غيرهم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12790/ما-الافضل-للمسلم-الوقف-ام-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55008.mp3","categories":["الوقف","صدقة التطوع"]},{"id":14590,"question":"إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (س. ح. أ) بعثت برسالة تقول فيها: هذه أول رسالة أكتبها إليكم، بعد أن وجدت أن هذا البرنامج هو خير الدروب التي تضيء للمسلم، ونحن معشر المسلمين دائمًا ما نحتاج لمثل هذه الأشياء تنير لنا طريق الدين، وسنة الرسول ﷺ، وأنا من المداومين على الاستماع لهذا البرنامج، وعليه وبعد أن وجدت طريقًا يمكن للإنسان أن يسأل فلدي سؤال عسى أن أجد الرد عليه وهو:أنا متزوجة ولدي طفل، وكنت حاملًا وزوجي يعمل بالسعودية، وعندما حضر إلينا بالسودان، قد نزل بمنزل شقيقه لضيق منزلنا، وقد أحضر إلي أشياء خاصة، وعندما أراد أن يسلمني هذه الأشياء قام بقسمتها بيني وبين زوجة شقيقه بالنصف، لدي سؤال:هل يجوز شرعًا هذه القسمة؟ وأنا كزوجة في الشرع، أريد ردًا واضحًا بما أني قد تضررت من هذه القسمة، وأرى كأنها ضرتي، وفي الختام أرجو أن أجد الرد.والسلام عليكم ورحمة الله.","title":"حكم إعطاء الرجل زوجة أخيه عطية مثل زوجته","answer":"الجواب: لا حرج في هذه القسمة، الزوج له الحرية في أن يعطيك، ويعطي زوجة أخيه، وزوجة عمه وزوجة أبيه، وله أن يعطي أيضًا من يرى من قريباته، لا حرج عليه في ذلك، ولا يجوز لك أن تكرهي ذلك، أو تضرري من ذلك، أو يكون عليك مشقة من ذلك إذا أحسن إليك، وأعطاك ما يجب لك من الكسوة والنفقة، فلا حرج عليه، إذا وسع الله عليه، وأحسن إلى زوجة أخيه من باب الصلة، ومن باب البر بأخيه، والمجاملة لأخيه، كونه سكن عندهم أيضًا، هذا من مكارم الأخلاق، ومحاسن الأعمال أن يكرم زوجة أخيه وزوجة عمه وزوجة أبيه.  وكذلك من مكارم الأخلاق أن يحسن إلى جيرانه وأقاربه جميعًا من ذكور وإناث. فينبغي أن تعينيه على هذا الخير، وأن تكوني زوجة صالحة تعين على الخير، وتساعد على بر الوالدين، وعلى صلة الرحم، وعلى إكرام الجيران، إذا أعطاك حقك، فإذا أعطاك ما يجب من الكسوة اللائقة، والحاجات اللائقة، ثم وسع الله عليه، وأعطى زوجات إخوته، أو أعطى أخواته أو عماته أو خالاته، أو نساء جيرانه على وجه ليس فيه ريبة ولا فتنة، فلا بأس بذلك، والحمد لله، هذا كله عمل طيب مشكور، ينبغي لمثلك أن يساعده على هذا، ويشكره على هذا؛ لأنه من مكارم الأخلاق، ومحاسن الأعمال إذا أدى حقك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13087/حكم-اعطاء-الرجل-زوجة-اخيه-عطية-مثل-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63510.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15141,"question":"هذا السائل يقول -يا سماحة الشيخ- من السودان: هل يجوز لي أن أمنع الهبة كالنخيل التي وهبها جدي تقربًا للسيد أو الولي؟","title":"حكم منع الولد ما أوقفه والده للأضرحة","answer":"الجواب: إذا كان جدك أو أبوك وقف نخلات، أو بيت على ضريح فلان، يبنى منه عليه، أو ينفق منه على تطييب المحل، أو البناء عليه، أو تجصيصه، أو ما أشبه ذلك، فالوقف باطل، هذا الوقف باطل، وهو يكون للورثة، يكون وقفًا باطلًا، ويكون للورثة، ولا يعتمد؛ لقوله ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد فلا بد أن تكون الأوقاف على الوجه الشرعي، فالوقف الذي لا يوافق الشرع يكون باطلًا. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13637/حكم-منع-الولد-ما-اوقفه-والده-للاضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56410.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15209,"question":"يقول: ما حكم قراءة القرآن في المسجد بصوت عالٍ قبل الصلاة، وبحضور كثير من المصلين كل يقرأ على حدة؟","title":"ما حكم رفع الصوت بقراءة القرآن في المسجد؟","answer":"الجواب: السنة عدم الرفع، ما ينبغي الرفع، يكره الرفع أو يحرم؛ لأنه يؤذي، فهذا الذي في المسجد السنة له أن يخفض صوته، حتى لا يتأذى به مصل، ولا قارئ؛ لأن الناس كل واحد قد يحب أن يقرأ، أو يصلي، فإذا كان من حوله يرفع صوته بالقراءة شوش عليه صلاته، وشوش عليه قراءته.  فالسنة أنه يخفض صوته خفضًا لا يضره، ولا يشوش على من حوله، يعني: خفضًا مناسبًا، يقرأ به قراءة مناسبة، ليس فيها تشويش على من حوله. وقد ثبت عن النبي ﷺ أنه خرج ذات يوم على الناس في مسجده، وهم يصلون في الليل، وبعضهم يرفع صوته على بعض، فقال: كلكم يناجي الله، فلا يؤذ بعضكم بعضًا هذا معناه: اخفضوا أصواتكم، لا يؤذي بعضكم بعضًا برفع الصوت. وهذا شيء مشاهد، شيء معقول، إذا كان يليك من يرفع صوته شوشت عليك قراءتك وصلاتك، فإما أن تنصت له، وإما أن تشوش أنت في صلاتك وفي قراءتك، فلهذا الواجب على من يقرأ في الصفوف أكرر هذا الواجب أو المتأكد ألا يجهر، بل يخفض صوته، ولا يجهر حال قراءته في الصف، حتى لا يتأذى به من حوله من المصلين والقارئين. أما إذا كان عندك جماعة محدودة، يرضون بذلك، يسمعون له، فلا بأس، إذا كانت جماعة قليلة في المسجد ينتظرون ما هناك من يصلي، ولا يقرأ، ويحبوا أن يسمعوا صوته، فلا بأس، أما إذا كان هناك من يصلي، وهناك من يقرأ لا، لا يرفع صوته، نعم.","link":"https://binbaz.org.sa/fatwas/13717/ما-حكم-رفع-الصوت-بقراءة-القران-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67205.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":15215,"question":"يقول: ما حكم قراءة القرآن في المسجد بصوت عالٍ قبل الصلاة، وبحضور كثير من المصلين كل يقرأ على حدة؟","title":"ما حكم رفع الصوت بقراءة القرآن في المسجد؟","answer":"الجواب: السنة عدم الرفع، ما ينبغي الرفع، يكره الرفع أو يحرم؛ لأنه يؤذي، فهذا الذي في المسجد السنة له أن يخفض صوته، حتى لا يتأذى به مصل، ولا قارئ؛ لأن الناس كل واحد قد يحب أن يقرأ، أو يصلي، فإذا كان من حوله يرفع صوته بالقراءة شوش عليه صلاته، وشوش عليه قراءته.  فالسنة أنه يخفض صوته خفضًا لا يضره، ولا يشوش على من حوله، يعني: خفضًا مناسبًا، يقرأ به قراءة مناسبة، ليس فيها تشويش على من حوله. وقد ثبت عن النبي ﷺ أنه خرج ذات يوم على الناس في مسجده، وهم يصلون في الليل، وبعضهم يرفع صوته على بعض، فقال: كلكم يناجي الله، فلا يؤذ بعضكم بعضًا هذا معناه: اخفضوا أصواتكم، لا يؤذي بعضكم بعضًا برفع الصوت. وهذا شيء مشاهد، شيء معقول، إذا كان يليك من يرفع صوته شوشت عليك قراءتك وصلاتك، فإما أن تنصت له، وإما أن تشوش أنت في صلاتك وفي قراءتك، فلهذا الواجب على من يقرأ في الصفوف أكرر هذا الواجب أو المتأكد ألا يجهر، بل يخفض صوته، ولا يجهر حال قراءته في الصف، حتى لا يتأذى به من حوله من المصلين والقارئين. أما إذا كان عندك جماعة محدودة، يرضون بذلك، يسمعون له، فلا بأس، إذا كانت جماعة قليلة في المسجد ينتظرون ما هناك من يصلي، ولا يقرأ، ويحبوا أن يسمعوا صوته، فلا بأس، أما إذا كان هناك من يصلي، وهناك من يقرأ لا، لا يرفع صوته، نعم.","link":"https://binbaz.org.sa/fatwas/13717/ما-حكم-رفع-الصوت-بقراءة-القران-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67205.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":15286,"question":"سؤالها الآخر تقول: والدي من ذوي الأموال والعقارات، وله أولاد ذكور ومن الإناث، أنا وأختي، ولكنه لا يعدل بيننا في الهبات؛ فهو يعطي الأولاد أموالًا نقدًا وعقارات بدون مقابل، ولكي يتخلص من مطالبتنا يسجل عقود بيع بينهم صورية، وإذا طالبنا يهددنا بإعطائهم ما تبقى وحرماننا من كل شيء. علمًا أنه يصلي ويصوم ويقرأ القرآن، وإذا قلنا له: هذا حرام عليك يستهزئ بنا ويسخر منا، وحتى أختي الثانية تسبب في طلاقها من زوجها منذ ثلاثين سنة، ورفض تزويجها مرة أخرى حتى بلغ عمرها الآن خمسين سنة، ومع ذلك لا ينفق عليها، بل إخوتي مرة يعطفون عليها ويعطونها، ومرة أخرى يطردونها بسبب تأثير والدي عليهم، فقد زرع الكراهية في نفوسهم نحونا، إضافة إلى ما جرت عليه العادة عندنا من عدم تزويج الفتاة إلا من ابن عمها مهما كان، فما رأيكم في هذا؟ وبماذا تنصحون والدنا هذا؟","title":"حكم من لا يعدل بين أولاده في العطايا ويعضل بناته","answer":"الجواب: أولاً: الواجب على الرجل أن يتقي الله في أولاده، وأن يعدل بينهم في العطية، وليس له الجور والحيف، بل يجب أن يعدل بينهم في العطية، فيعطي الرجل ضعف المرأة كالميراث، هذا هو الصواب؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم ولما جاءه بشير بن سعد الأنصاري  وقد أعطى ابنه النعمان غلامًا قال له النبي -عليه الصلاة والسلام-: أكل ولدك أعطيته مثل هذا؟ قال: لا، قال: اتقوا الله واعدلوا بين أولادكم وقال لما أشهده: إني لا أشهد على جور فهذا يدل على أن التفضيل بين الأولاد، أو إعطاء بعضهم، وترك البعض جور وظلم، وهذا هو الصواب من أقوال أهل العلم كما دل عليه الحديث الشريف. فالواجب على أبيك تقوى الله، وأن يعدل في أولاده، وإذا لم يعدل وجب على الحاكم الشرعي أن يلزمه بالعدل، وأن ينقض العطايا التي فيها الحيف والجور، وإذا كانت بصور بيع لا حقيقة له يبطل هذه البيوع الباطلة إذا ثبت لدى الحاكم أنها حيلة، فالبيع الذي يكون بالحيلة باطل وجور وظلم، والله سبحانه أوجب على الآباء والأمهات العدل في أولادهم وألا يجوروا، وأن يحرصوا على أن يكونوا في البر لهم سواء. وكذلك ليس للوالد أن يمنع بناته الزواج، بل عليه أن يساعد في الزواج، ولا يجوز له أن يجبرها على ابن عمها، بل إذا جاء الكفء من بني عمها أو غيرهم وجب على الولي التزويج، سواء كان الولي أبًا أو غير أب، هذا هو الواجب، وقد جاء في الحديث: إذا خطب إليكم من ترضون دينه وأمانته فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد كبير والله -جل وعلا- قال: فََلا تَعْضُلُوهُنَّ[البقرة:232] نهى الأولياء عن العضل، فإذا عضل الوالد زالت ولايته، وساغ للقاضي أن يولي غيره من بقية العصبة الأقرب فالأقرب. فالمقصود: أن والدك إذا كان عمله ما ذكرت فقد أساء وعصى ربه، فعليه التوبة إلى الله، وعليه أن يعدل بين أولاده، وعليه أن يرد العقود الباطلة التي تحيل بها وسماها بيعًا، وليست ببيع، وإنما هي عطايا، وعلى الحاكم الشرعي إذا علم هذا بالبينة أن يبطل العقود، وأن يرد العطايا الجائرة، وأن يلزمه بالتسوية بين أولاده. كما أن على القاضي أن يلزمه بتزويج البنت التي يخطبها الكفء، يلزم القاضي أن يلزمه بالزواج، أو يعزله عن هذا الأمر، ويحكم عليه بالعضل، ويسمح للأقرب من العصبة بعد الوالد بالتزويج، هذا هو الواجب على الأولياء وعلى حكام الشرع في علاج، هذه المسائل، نسأل الله للجميع الهداية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13785/حكم-من-لا-يعدل-بين-اولاده-في-العطايا-ويعضل-بناته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_681/nour_68103.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15317,"question":"هذه رسالة من المستمع (ع. ع. س. الغامدي) يقول: كان والدي -رحمه الله- قد أوقف أرضًا زراعية بجانبها بئر، على أن يصرف ريع هذه الأرض في استمرار دلو على البئر بمعنى لغرض سقاية المارة الذين كانوا في السابق يمرون بهذه الأرض مشيًا على أقدامهم، أو ركوبًا على دوابهم من الحيوانات، فأوقف الأرض لهذا الغرض، والآن لم يعد هناك من يمر بهذه الأرض من المشاة، حتى يستفيدوا من السقي من هذه البئر بواسطة الدلو الموقوفة الأرض لأجل استمرار بقائه، وأيضًا الأرض تركت من الزراعة؛ لذا فليس لها ريع الآن.فأرشدونا إلى العمل الأفضل لنا فعله تجاه هذا الوقف.","title":"كيفية التصرف في الوقف الذي لم يعد يستفاد منه","answer":"الجواب: ينبغي في مثل هذا التشاور مع قاضي البلد في بيع الوقف هذا، وصرف ثمنه في وقف أنفع للمسلمين في بلد تنتفع بهذا الوقف في البركة ماء ينتفع بها الناس، أو في إيجاد حوض، بركة من الماء لسقي مواشيهم، أو ما أشبه ذلك مما يحل محل الدلو الأولى.  يتشاور صاحب الوقف هذا مع فضيلة القاضي فيما تنقل إليه هذه الأرض، تباع ويصرف ثمنها فيما يناسب ويجانس ما أراده الواقف السابق، فإن لم يتيسر شيء من ذلك صرف ثمنها فيما ينفع المسلمين من تعمير المساجد التي هي في حاجة إلى التعمير، أو ما أشبه ذلك مما يراه القاضي نافعًا للمسلمين، ومن جملة المصالح العامة، نعم.\nالمقدم: يعني: لو أنفق نقدًا مثلًا سلم إلى أحد من المحتاجين أو وزع؟\nالشيخ: لا، إذا ينصرف في مثله يكون أحسن، إذا تيسر صرفه في بركة تنفع المسلمين في بعض القرى، أو صرفه في إيجاد بئر تسقي بعض المارة، أو تسقي بعض الفقراء في بعض القرى المحتاجة، أو بعض البادية إذا وجد شيء من هذا، فهو أفضل، حتى يجانس ما أراده الواقف، فإن ما تيسر صرف فيما هو أنفع وأبقى مثل المساجد وأشباهه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13819/كيفية-التصرف-في-الوقف-الذي-لم-يعد-يستفاد-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67606.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15337,"question":"خالد صالح من اليمن، حضرموت، يقول: سماحة الشيخ، أسأل عن حكم الشرع في نظركم في نقل فرش قديم تم الاستغناء عنه من مسجد إلى مدرسة أو مسجد آخر. علمًا بأن هذا المسجد أو هذه المدرسة محتاجة إلى فرش، حتى وإن كانت قديمة؛ وذلك لغرض فرشه للمصلين في المسجد أو للطلبة في المدرسة.فأفيدونا بذلك.","title":"حكم نقل أثاث مسجد إلى مسجد آخر أو مدرسة","answer":"الجواب: إذا فضل عن المسجد شيء من أثاثه ينقل إلى مسجد آخر محتاج، فإذا ما وجد مساجد محتاجة يصرف في الفقراء والمساكين، أو في حاجات المدرسة لا بأس، أما إذا وجد مسجد محتاج ينقل من مسجد إلى مسجد؛ لأن مراد الموقف نفع المصلين والتقرب بما يعين المصلين على أداء صلاتهم، فإذا كانت المساجد مستغنية، فلا بأس أن يصرف الفاضل في الفقراء والمساكين، أو في حاجة مدرسة للطلاب، نعم.\nالمقدم: إذًا سماحة الشيخ نقل هذه الفرش من مسجد إلى مدرسة ما فيه شيء يا شيخ؟\nالشيخ: إذا كان ما هناك مسجد محتاج له، أما إذا كان هناك مسجد محتاج ينقل لمسجد آخر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13834/حكم-نقل-اثاث-مسجد-الى-مسجد-اخر-او-مدرسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56614.mp3","categories":["المساجد ومواضع السجود","الوقف"]},{"id":15482,"question":"السائلة في آخر أسئلتها تقول: سماحة الشيخ، جزاكم الله عنا وعن جميع المسلمين خير الجزاء، هل تعتبر الهدية رشوة في هذه الحالة، حيث بأنها قامت بعمل خير، وهو تدريس بنت الجيران، وقالت: إذا نجحت فلك هدية، وقلت لها: لا أريد هدية؛ لأنني أعمل هذا لله، ولكنها أصرت عليها، فما حكم أخذ هذه الهدية سماحة الشيخ؟","title":"ما حكم قبول الهدية على عمل الخير؟","answer":"الجواب: ما دمت قصدت وجه الله في عدم أخذ الهدية فالأحوط لك أن لا تأخذي شيئًا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14008/ما-حكم-قبول-الهدية-على-عمل-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56903.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15510,"question":"هذه رسالة من السائل أبو إهاب مصري، يعمل بالكويت، بعث بعدة أسئلة في سؤاله الأول يقول: أنجب والدي ستة أولاد وبنتًا واحدة، ولقد جاهد -رحمه الله- حتى أتم تعليمنا إلا واحدًا من إخوتي شاء الله أن لا ينال حظه من التعليم مثلنا، وذلك لرغبة من الوالدة في أن يظل مع والده يعمل معه في فلاحة الأرض، حيث أننا من أبناء الريف، وقبل وفاة الوالد طلبت أنا من والدي أن يخص أخي المذكور بقدر معين من الأرض التي يملكها عوضًا له عن جهده طوال سنوات عدة، ولكونه لم ينل حظه من التعليم مثلنا، والحقيقة أنه -رحمه الله- رفض ذلك مرارًا، ولكنه أمام إلحاحي وإلحاح الوالدة وبعض الإخوة وافق على أن يحرر لأخي عقد بيع وشراء صوري لقطعة محددة من الأرض، ولكن دون أن يقبض منه أي ثمن، بل أخذ عليه صكًا بمبلغ سبعمائة جنيه، فما مدى صحة هذا العقد الذي تم بين الوالد وبين أخي؟علمًا بأن العقد موجود عندي بصفة أمانة لحين إتمام الإجراءات، وهل الصك الذي أخذه والدي على أخي يدخل ضمن تركته ويطالب به أخي أم لا؟","title":"حكم الأرض التي باعها الأب لأحد أبنائه قبل موته","answer":"الجواب: إذا كان الواقع ما ذكره السائل فالصك المذكور لا عبرة به؛ لأنه كذب وحيلة؛ فلا وجه له، لكن إذا سمح إخوته الورثة جميعًا بهذه القطعة لهذا الأخ للسببين المذكورين؛ لكونه ساعد أباه، ولكونه لم يتعلم، فلا بأس إذا سمحوا له بهذه القطعة، أو سمح بعضهم، فمن سمح منهم سقط حقه من هذه القطعة، ومن لم يسمح فهو على حقه، أما هذا العقد المزور فلا قيمة له، ولا يلتفت إليه، نعم.\nالمقدم: إنما تعتبر كهبة يعني من الورثة.\nالشيخ: إذا سمحوا بها.\nالمقدم: إذا سمحوا بها صحيحة. الشيخ: ومن لم يسمح فهو على حق.","link":"https://binbaz.org.sa/fatwas/14067/حكم-الارض-التي-باعها-الاب-لاحد-ابناىه-قبل-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70303.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":16271,"question":"لها سؤال قريب في معناه من الأول تقول: إذا أهدى لي شخص طعامًا، سواءً كان ذلك الشخص جارًا، أو قريبًا، أو صديقًا، وهو لا يصلي، ولا يصوم، ويشرب الخمر، هل يجوز قبول هديته؟","title":"حكم قبول هدية من لا يصلي ويجاهر بالمعاصي","answer":"الجواب: هذا فيه تفصيل: إن كان قبولها يرجى فيه خير، وأن الله يهديه، ويقبل من المهدى إليه النصيحة، ويتأثر؛ فلا مانع من قبولها، لكن إذا كان فيها لحم لا، لا تأكل اللحم إذا كان لا يصلي، إلا إذا كانت فاكهة شيء ما يحتاج ذبحًا، فاكهة، أو شبه فاكهة، لا بأس.  أما إذا كان لا، معاند، ولا يرجى فيه خير، لا تقبل هديته، اهجره، ولا تقبل هديته، لعل الله يهديه، لا تقبل هديته، ولا تقبل دعوته، ولا تزوره، بل يستحق الهجر؛ لتركه الصلاة، وإعلانه الخمر، والمعاصي الظاهرة، فهذا يستحق الهجر؛ لعله يتوب، فيتوب الله عليه. أما إذا كان في قبول هديته مصلحة شرعية، أو في زيارته مصلحة شرعية للدعوة إلى الله، وتوجيهه إلى الخير، وإنكار المنكر عليه؛ لعل الله يهديه بأسبابك، فهذا لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14978/حكم-قبول-هدية-من-لا-يصلي-ويجاهر-بالمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80907.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":16285,"question":"لها سؤال قريب في معناه من الأول تقول: إذا أهدى لي شخص طعامًا، سواءً كان ذلك الشخص جارًا، أو قريبًا، أو صديقًا، وهو لا يصلي، ولا يصوم، ويشرب الخمر، هل يجوز قبول هديته؟","title":"حكم قبول هدية من لا يصلي ويجاهر بالمعاصي","answer":"الجواب: هذا فيه تفصيل: إن كان قبولها يرجى فيه خير، وأن الله يهديه، ويقبل من المهدى إليه النصيحة، ويتأثر؛ فلا مانع من قبولها، لكن إذا كان فيها لحم لا، لا تأكل اللحم إذا كان لا يصلي، إلا إذا كانت فاكهة شيء ما يحتاج ذبحًا، فاكهة، أو شبه فاكهة، لا بأس.  أما إذا كان لا، معاند، ولا يرجى فيه خير، لا تقبل هديته، اهجره، ولا تقبل هديته، لعل الله يهديه، لا تقبل هديته، ولا تقبل دعوته، ولا تزوره، بل يستحق الهجر؛ لتركه الصلاة، وإعلانه الخمر، والمعاصي الظاهرة، فهذا يستحق الهجر؛ لعله يتوب، فيتوب الله عليه. أما إذا كان في قبول هديته مصلحة شرعية، أو في زيارته مصلحة شرعية للدعوة إلى الله، وتوجيهه إلى الخير، وإنكار المنكر عليه؛ لعل الله يهديه بأسبابك، فهذا لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14978/حكم-قبول-هدية-من-لا-يصلي-ويجاهر-بالمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80907.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":16340,"question":"عندنا وعند سنة الوليمة في الزواج يكون هناك دفتر يسجل عليه أسماء الذين يدفعون نقودًا للعريس، وعندما تكون هناك وليمة عند أحد الذين دفعوا للعريس، يخرج العريس الأول الدفتر ليرى كم دفع له من قبل هذا العريس الثاني، ثم يدفع هو زيادة على ما دفعه له الأول، فهل هذا شيء مباح؟الشيخ: أعد.المقدم: يقول: عندنا وفي بلدنا -ويسمي بلده سماحة الشيخ- وعند سنة الوليمة في الزواج يكون هناك دفتر يسجل عليه أسماء الذين يدفعون نقودًا للعريس، وعندما تكون هناك وليمة عند أحد الذين دفعوا للعريس يخرج العريس الأول الدفتر ليرى كم دفع له هذا العريس، ثم يدفع هو زيادة على ما دفعه له الأول، فهل في هذا شيء من الحرمة، وهل هو نوع من الربا؟ جزاكم الله خيرًا.","title":"ما حكم دفع مبالغ للعريس كمساعدة؟","answer":"الجواب: لا حرج في ذلك إذا كانت عادة عندكم لا حرج، الحمد لله؛ لأنه من باب المساعدة، والتعاون على الخير، وهذه عادة بين الناس مواساة للعريس بالمال، وبغير المال من الأشياء الأخرى، كل هذا تختلف فيه عادات الناس، هذا يدفع دراهم، وهذا يدفع أشياء أخرى. فالمقصود: أن هذه العادات لا حرج فيها في التعاون على الخير على البر والتقوى، ولا بأس إن شاء الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15034/ما-حكم-دفع-مبالغ-للعريس-كمساعدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71403.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17052,"question":"أحمد سالم له هذا السؤال، يقول: سماحة الشيخ! عندنا أراضي زراعية وقف لمسجد صغير وقديم، فهل يجوز لنا أن نبيع بعض هذه الأوقاف لمصلحة إنشاء مسجد كبير، ومتسع للقرية؟ علمًا بأن أصحاب الوقف أموات، وهذه المزارع الموقوفة لا يستفيد المسجد القديم من وقفها بشيء؛ لأنها بأيدي أشخاص لا يؤدون حقها.","title":"حكم بيع أراضي الوقف وبناء مسجد بثمنها","answer":"الجواب:  عليكم مراجعة المحكمة، هذه المسائل من خصائص المحاكم، فعليكم أن تراجعوا المحكمة في هذا الأمر العظيم، وفيما تراه المحكمة الكفاية، إن شاء الله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15841/حكم-بيع-اراضي-الوقف-وبناء-مسجد-بثمنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58727.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17114,"question":"أيهما أفضل: الإثابة على الهدية عندما تعطى لي، أم إنفاق المال على الوالدين والأقربين؟ علمًا بأنني لا أستطيع الجمع بينهما؟","title":"استحباب الإثابة على الهدية","answer":"الجواب: كان النبي ﷺ إذا أهدي إليه هدية يقبلها، ويثيب عليها من جاء له هدية، وصاحبها يمكن أن يقبل الثواب يثاب، يعني: يعطى مقابل. أما إذا كان لا، ما يريد الثواب فلا حرج، إذا كان إنما هي صدقة لأجل فقره، أعطاه إياه لأجل فقره، أو أعطاه إياه من الزكاة هذا ما يحتاج أن يثاب، أما الهدية العادية التي للتحبب فالأفضل أن يقابل، ويعطى مقابل هديته، كان الرسول ﷺ يقبل الهدية ويثيب عليها، اللهم صل عليه. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15921/استحباب-الاثابة-على-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58911.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17558,"question":"هذا سائل من سوريا فهمت الحقيقة من رسالته الطويلة وأسلوبه بحكم الشرع في نظركم فضيلة الشيخ في الأب الذي يفرق بين أولاده في الأعطية؟","title":"الواجب العدل بين الأبناء في العطية","answer":"الجواب: لا يجوز، الواجب على الآباء العدل؛ لأنه ثبت عن النبي ﷺ أنه قال: اتقوا الله واعدلوا بين أولادكم، فلا يجوز للأب ولا للأم التفضيل بين الأولاد بل يجب التسوية للذكر مثل حظ الأنثيين، هذا هو الواجب على الرجل والمرأة في أولادهم، لكن لو كانوا مرشدين، وسمحوا أن يخص واحد منهم بشيء فلا بأس إذا كانوا مرشدين وسمحوا لأبيهم أو لأمهم أن تخص أحدًا منهم بشيء لأسباب اقتضت ذلك فلا بأس، أما أن يخص أحد دون أحد، أو يفضل أحد على أحد؛ فلا يجوز إلا بإذن المرشدين. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16487/الواجب-العدل-بين-الابناء-في-العطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77523.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17670,"question":"من أسئلة السائلة هيلة المرشد من القصيم تقول: يا سماحة الشيخ حفظكم الله، هل تكفر الذنوب بالهدايا والأعطيات للفقراء والمحتاجين وذوي القرابة والأصدقاء؟","title":"هل الهدايا والأعطيات تكفر الذنوب؟","answer":"الجواب: الصدقات تطفئ الخطيئـة كما قال ﷺ: الصدقة تطفئ الخطيئة كما يطفئ الماء النار الصدقات ثوابها عظيم وأجرها كبير، وهي من أسباب تكفير الخطايا وحط السيئات.\nأما الهدايا فيها تفصيل، الهدايا إذا أهداها لقريبه لصلة الرحم هذه من أسباب تكفير السيئات، صلة الرحم عمل صالح، أما إذا أهداها لشيء آخر؛ لمجاملة أو لطلب مكافأة، هذا لم يقصد بها عملًا صالح.\nأما إذا أهداها لقريبه أو لأرحامه أو لفقير تسمى صدقة، وللقريب تسمى صلة، صلة رحم يؤجر عليها. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16601/هل-الهدايا-والاعطيات-تكفر-الذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59434.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17879,"question":"إذا جاء مصحف هدية لأحد الأشخاص أو وزع على المدارس أو غيرها، وكان عليه كلمة وقف لله، ولكن لم يأخذ من المسجد، هل في ذلك شيء؟","title":"حكم توزيع المصاحف الموقوفة","answer":"الجواب: لا. ما فيه بأس، للقراءة، توزيعه للقراءة فيه، لكن لا يباع، ما دام كتب عليه وقف لا يباع. نعم.","link":"https://binbaz.org.sa/fatwas/16885/حكم-توزيع-المصاحف-الموقوفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59810.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":18075,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أخوكم محاسب جلال الدين عبد العال مصري ويعمل في جدة، أخونا له ثلاثة أسئلة، في سؤاله الأول يقول: هل أخذ مصحف شريف من أحد المساجد للقراءة فيه دون علم أحد بالمسجد يعتبر سرقة؟ وكيف التكفير عن ذلك إذا كانت سرقة؟","title":"حكم أخذ المصحف من المسجد إلى البيت","answer":"الجواب: لا يجوز لأحد أن يأخذ من المسجد ما وضع فيه من المصاحف إلى بيته أو إلى بلده، بل يجب أن يبقى في المسجد؛ لأن الذي وضعه في المسجد أراد به نفع المسلمين الذين يأتون المسجد فيقرأ فيه مادام في المسجد، ثم يضعه في المسجد ولا يخرج به خارج المسجد، إلا إذا وضع في مكان معروف للتوزيع وجاء به أصحابه للتوزيع وبينوا للمؤذن أو الإمام أن هذا للتوزيع فهذا شيء آخر. أما ما يوضع في الدواليب في المسجد أو في الرفوف في المسجد لينتفع بذلك زوار المسجد والمصلون في المسجد، فليس لأحد أن يأخذه من المسجد؛ لأن الواقف إنما أراد به البقاء في المسجد، فمن أخذ شيئًا من هذا فالواجب عليه أن يعيده وإن كان تلف أو ضيعه فعليه إبداله بمثله أن يشتري مثله ويضعه في المسجد بدلًا مما أخذ من المسجد مع التوبة والاستغفار. نعم. المقدم: جزاكم الله خيرًا. نصيحتكم سماحة الشيخ للقائمين على أمر المساجد كالمؤذنين والخدم هل يسمحون لأحد باستعارة مصحف من المسجد ثم يعيدوه أو ما أشبه ذلك؟ الشيخ: ليس لهم لا، ليس للإمام ولا للمؤذن أن يعيروا في ذلك، إلا إذا كان الذي جعله في المسجد سمح لهما بهذا، أما إذا كان وضعه في المسجد ولم يسمح لهما بهذا فليس لهما أن يعيرا أحدًا. نعم. المقدم: جزاكم الله خيرًا. الكفارة أخونا يسأل عنها؟ الجواب: ليس عليه كفارة إلا التوبة والاستغفار، وأن يعيد المصحف كما أخذه أو يعيد بديلًا منه إن كان ضاع عليه أو تلف. المقدم: أحسنت، وهذا كفارته؟ الشيخ: هذا كفارته، نعم، مع التوبة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17110/حكم-اخذ-المصحف-من-المسجد-الى-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_903/nour_90302.mp3","categories":["المساجد ومواضع السجود","الوقف","القرآن وعلومه"]},{"id":18144,"question":"يقول السائل من الكويت: هل يجوز وضع المصاحف في المساجد؟ وهل يكون لمن وضعها أجر على كل حرف يقرأ من هذا المصحف، ووضع هذا المصحف بنية أن يكون أجر القارئ للمتوفى فهل هذا مشروع؟","title":"ثواب من أوقف المصاحف في المسجد","answer":"الجواب: وضع المصاحف في المساجد مشروع؛ لأنه يعين من جاء للمسجد على القراءة، وصاحبه له أجر، يرجى له أجر كبير؛ لأنه ممن أعان على الخير، والرسول  يقول: والله في عون العبد ما كان العبد في عون أخيه، ويقول ﷺ: من كان في حاجة أخيه كان الله في حاجته. وإذا سبل المصاحف للأموات، أو كُتبَ علم؛ فلهم أجر في ذلك، إذا سبل مصحفًا، أو كتاب علم من كتب الحديث الشريف، أو من كتب التفسير، أو الفقه؛ فله أجر في ذلك، وإذا نوى هذا الوقف لأبيه أو أمه فله أجر في ذلك، وللموقوف له أجر في ذلك. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/17194/ثواب-من-اوقف-المصاحف-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78117.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18247,"question":"في آخر أسئلة هذه السائلة، تقول سماحة الشيخ: أنا أحب معلمتي تذكر بأنها .. تقول السائلة: أنا أحب معلمتي في الله، وفي نهاية الدراسة أهديت لها هدية من باب التآلف والمحبة بيننا، هل يجوز لي هذا؟","title":"حكم الهدايا بين الطلاب والمدرسين","answer":"الجواب: ترك الهدية أحوط؛ لأنه قد يسبب الميل إليك دون بقية التلميذات، ترك الهدية أولى وأحوط؛ لأن المدرسة من العمال، ولا تنبغي الهدية للعمال، فالأحوط لك والذي ينبغي أن لا تهدي شيئًا؛ لأن هذه الهدية قد تسبب ميلًا من المدرسة إليك، وحيفًا على البقية بسبب الهدية، فالأحوط والذي يظهر من الأدلة عدم الهدية للمدرسات والمدرسين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17296/حكم-الهدايا-بين-الطلاب-والمدرسين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78303.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18283,"question":"ننتقل إلى رسالة أخرى وصلت من الأخوين: محمود فرحات، وعبد الرحمن الشدوي من الظهران، الإخوان لهم مجموعة من الأسئلة يسألون في سؤالهم الأول ويقولون:هناك عادة متبعة بين أفراد إحدى القبائل، تتمثل بأنه يجب على كل من يحضر ختان المولود الذكر دفع مبلغ من المال للوالد يتراوح من خمسين إلى مائة ريال، ما رأي سماحتكم في هذه العادة من الناحية الشرعية؟","title":"حكم دفع الأموال لمن رزق بمولود يوم ختانه","answer":"الجواب: إذا كان من عادة القبيلة، أو من عادة الأقارب بينهم الإهداء إلى أصحاب المولود في وقت الختان، أو في وقت العقيقة، أو في أي وقت بعد الولادة، فلا حرج في هذا من باب التبرع، ومن باب التعاون لا نعلم بأسًا في ذلك، كما أن من عادة الكثير من الناس مساعدة المتزوج إذا بلغهم أنه سيتزوج، أو دعاهم إلى الوليمة ساعدوه في الزواج؛ كل هذا من باب التعاون على الخير. والمسلمون شيء واحد يتعاونون على البر والتقوى وعلى مصالحهم وعلى سد حاجة الفقير، ولا سيما إذا كان صاحب المولود فقيرًا؛ فإن مساعدته من أهم القربات، لا في العقيقة ولا في غيرها. نعم.","link":"https://binbaz.org.sa/fatwas/17332/حكم-دفع-الاموال-لمن-رزق-بمولود-يوم-ختانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_911/nour_91102.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18368,"question":"من إحدى الأخوات المستمعات، تقول: أختكم في الإسلام (د. ع. ح) من العريش، أختنا لها قضيةٌ تقول فيها: سيدة كانت متزوجة، فمات عنها زوجها، وترك لها ولدين، ولم يترك لها أي مال، فتركت الأولاد لأهلهم، وتزوجت من رجلٍ آخر، وأنجبت منه ولدًا وبنتًا، ثم قام هذا الرجل الذي تزوجته بكتابة قطعة أرضٍ زراعية لها، فهل يجوز أن تكتب هذه الأرض باسم أولادها من هذا الرجل؛ لأنها أرض أبيهم في الأصل، أم تترك الأرض يرث فيها أولادها من الرجل الأول؟ جزاكم الله خيرًا.","title":"هل يجوز تخصيص بعض الأولاد بالعطية؟","answer":"الجواب: الواجب عليها ترك الأرض للجميع، فليس لها أن تخص أولادها من الزوج الجديد، الأرض تكون للجميع، تعدل بينهم؛ يقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم ولو كانت الأرض من الزوج الجديد صارت ملكًا لها، فليس لها أن تعطيها أحدهم، وليس لها أن توصي بها لأحدهم، بل للجميع، تبقى في يدها، في ملكها، ويرثونها عنها، أو تقسمها بينهم لا بأس، أما أن تخص بها أحدًا منهم؛ فلا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17435/هل-يجوز-تخصيص-بعض-الاولاد-بالعطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73212.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19075,"question":"هذه أخت سائلة تقول: ما حكم تقديم الهدية بالنسبة للمعلمات يا سماحة الشيخ في آخر العام الدراسي؟","title":"حكم تقديم الطالبة هدية لمعلمتها","answer":"الجواب: تركه أولى لا، لا تعطي لا يعطين الهديات لا تقدم الطالبة هدية؛ لأن الهدية للمعلمة قد تفضي إلى المحاباة والحيف ولا ينبغي للمعلمة أن تقبل هدايا الطالبات؛ لأن هذا قد يفضي إلى اتهامها أو حيفها؛ ولأنها بمنزلة العمال وهدايا العمال غلول فينبغي للأمير والمعلم عدم قبول الهدايا ممن تحت يده حتى لا يجره ذلك إلى الحيف والظلم. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18246/حكم-تقديم-الطالبة-هدية-لمعلمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88322.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19250,"question":"تسأل أختنا هل يجوز للمعلمة قبول الهدية من الطالبات؟ وإذا كان لا يجوز لها ذلك فهل يجوز قبولها بعد انتهاء العام الدراسي وتسليم النتائج؟ وإذا كان ذلك أيضًا لا يجوز، فهل يجوز لها قبولها من الطالبات بعد انتهاء مدة تدريسها في تلك المدرسة إذا أرادت الانتقال من هذه المدرسة لمدرسة أخرى؟","title":"حكم قبول الهدية من الطلاب","answer":"الجواب: الذي ينبغي للمعلمة ترك قبول الهدايا؛ لأنها قد تجرها إلى الحيف، وعدم النصح في حق من لم يهد والزيادة في حق المهدية والغش، فالأحوط للمؤمنة في هذا أن لا تقبل الهدية من الطالبات بالكلية؛ لأن ذلك قد يفضي إلى ما لا تحمد عقباه، والمؤمن يحتاط لدينه ويبتعد عن أسباب الريبة والخطر. أما بعد انتقالها من المدرسة إلى مدرسة أخرى فلا يضر ذلك؛ لأن الريبة قد انتهت حينئذ والخطر مأمون، وهكذا بعد فصلها من العمل إذا أهدوا إليها شيئًا فلا بأس. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18443/حكم-قبول-الهدية-من-الطلاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73813.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19643,"question":"من جدة السائل (ع. ب. ي) يقول: سماحة الشيخ حفظكم الله، أنا متزوج من امرأة صالحة ولم يرزقني الله منها بولد، وقد أكد الأطباء على عدم قدرتها على الإنجاب ولا أملك غير البيت الذي نسكن فيه، فهل يمكنني أن أسجل البيت الذي نسكن فيه باسمها حتى يكون عونًا لها في حياتها، أم أن هذا محرم، علمًا بأنها زوجتي الوحيدة، ولا أنوي الزواج مرة أخرى ولي ستة من الإخوة والأخوات؟","title":"حكم الهبة للزوجة","answer":"الجواب: لا حرج في ذلك إذا أعطيتها بيتك وسجلته باسمها في صحتك فلا بأس، أما في حال المرض لا، أما في صحتك إذا أعطيتها بيتك أو أعطيتها شيئًا آخر من مالك فلا حرج في ذلك. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18924/حكم-الهبة-للزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94932.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19661,"question":"الحمد لله رب العالمين، والصلاة والسلام على أشرف المرسلين، نبينا محمد، وآله وصحبه أجمعين، أما بعد: فقد ورد إلي سؤال مضمونه: أن جماعة من المسلمين القاطنين في جنوب أفريقيا قد بنوا مسجدًا في حيهم، يصلون فيه الجمعة والجماعة والعيد، وقد أمرتهم حكومتهم بإخلاء ذلك الحي من السكان المسلمين وإبعادهم إلى جهة أخرى.فهل يجوز بيع المسجد المذكور بواسطة القاضي أو المتولي عليه، وعمارة مسجد آخر في الحي الجديد الذي يسكنون فيه؟ وهل يباع بشكله مسجدًا، أو يغير فيه كرفع المحراب والمنبر والمئذنة، وكل شيء يدل على كونه مسجدًا، أو يهدم ويباع أرضًا بيضاء، مع العلم أنه في هذه الحالة تنقص قيمته كثيرًا، بل لا يساوي شيئًا؟","title":"حكم نقل المسجد إذا تعطلت منفعته","answer":"الجواب: والجواب: لا ريب أن المسجد المذكور سوف تتعطل مصلحته إذا ارتحل المسلمون عن الحي الذي هو فيه، وإذا تعطلت منفعة الوقف سواء كان مسجدًا أو غيره جاز بيعه في أصح أقوال العلماء، وتصرف قيمته في وقف آخر بدل منه، مماثل للوقف الأول حيث أمكن ذلك. وقد روي عن أمير المؤمنين عمر بن الخطاب  أنه أمر بنقل مسجد الكوفة إلى مكان آخر لمصلحة اقتضت ذلك. فتعطل المنفعة أولى بجواز النقل، والمسألة فيها خلاف بين العلماء، ولكن القول المعتمد جواز ذلك؛ لأن الشريعة الإسلامية الكاملة جاءت بتحصيل المصالح وتكميلها، وتعطيل المفاسد وتقليلها، وأمرت بحفظ الأموال ونهت عن إضاعتها، ولا ريب أن الوقف إذا تعطل لا مصلحة في بقائه، بل بقائه من إضاعة المال. فوجب أن يباع ويصرف ثمنه في مثله، إلا أن يكون بيع بعضه يكفي لإصلاحه، فإنه يباع بعضه، ويصرف ثمنه في إصلاح الباقي. أما هذه الصورة المسئول عنها، فلا يمكن حصول المنفعة إلا ببيع الجميع، فيباع المسجد كله على حاله من دون نقص، ويصرف ثمنه في عمارة المسجد الجديد في الحي الذي تحول إليه المسلمون، وإذا بيع زال عنه حكم المسجد، وصار كسائر البقاع، يجوز اتخاذه مزرعة وحوانيت ونحو ذلك، وانتقل حكم المسجد إلى المسجد الجديد. وأما إزالة ما يدل على أنه مسجد بعد العزم على بيعه، كالمئذنة ونحوها، فلم أقف فيه على كلام لأحد من أهل العلم، والأقرب -والله أعلم- أن إزالة ذلك أولى، ولا سيما إذا كان بين الكفرة؛ لأنهم قد يقصدون إغاظة المسلمين بامتهانه؛ نظرًا إلى أنه كان مسجدًا، وإن كان حكمه قد زال، ولكنهم لا ينظرون إلى الأحكام، ولكنهم ينظرون إلى الصورة الظاهرة، فإذا أزيلت أمارات المسجد البارزة، كالمئذنة والمحراب، زال هذا المحذور. والله  أعلم. ونسأل الله سبحانه أن يصلح أحوال المسلمين، ويولي عليهم خيارهم، ويرفع شأنهم في كل مكان، وأن يذل أعداء الإسلام، ويكفي المسلمين شرهم؛ إنه على كل شيء قدير، وصلى الله وسلم على عبده ورسوله محمد، وآله وصحبه[1]. نائب رئيس الجامعة\nالإسلامية بالمدينة المنورة\nعبدالعزيز بن عبدالله بن باز","link":"https://binbaz.org.sa/fatwas/18953/حكم-نقل-المسجد-اذا-تعطلت-منفعته","audio":"","categories":["المساجد ومواضع السجود","الوقف"]},{"id":19690,"question":"يوجد مسجد في الولايات المتحدة الأمريكية جُمع له مال وبني، وبقي من المال كثير، ويوجد في منطقة أخرى مسجد وحوله جالية إسلامية كبيرة، ويتطلب بناء مكتبة ومدرسة وبعض الملاحق، ويريد بعض القائمين عليه أخذ شيء من المال الموجود عند القائمين على المسجد الأول، ويمانع أصحاب المسجد الأول؛ بحجة أن المال للمسجد الأول، ويقولون: إذا أفتى الشيخ/ عبدالعزيز بن باز في جواز نقل المال من ذاك إلى هذا، فلا مانع لدينا من ذلك. نرجو الإفادة عن ذلك؟","title":"حكم نقل مال مسجد لآخر","answer":"الجواب:\n\nإذا كان المسجد الأول الذي جمع له المال قد كمل واستغني عن المال، فإن الفاضل من المال يصرف لتعمير مساجد أخرى، مع ما يضاف إليها من مكتبات ودورات مياه ونحو ذلك كما نص على ذلك أهل العلم في كتاب الوقف؛ ولأنه من جنس المسجد الذي تُبرع له، ومعلوم أن المتبرعين إنما قصدوا المساهمة في تعمير بيت من بيوت الله، فما فضل عنه يصرف في مثله، فإن لم يوجد مسجد محتاج، صرف الفاضل في المصالح العامة للمسلمين، كالمساجد والأربطة والصدقات على الفقراء، ونحو ذلك، والله ولي التوفيق[1].\n\n\n\n\tنشر في كتاب (فتاوى إسلامية)، من جمع الشيخ /محمد المسند ج3، ص: 24. (مجموع فتاوى ومقالات الشيخ ابن باز 20/14).","link":"https://binbaz.org.sa/fatwas/18989/حكم-نقل-مال-مسجد-لاخر","audio":"","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":19693,"question":"رجل له أربعة أولاد، منهم واحد موظف ومتزوج وله خمسة أولاد، وجزء من المال الذي بيد والده توفير من رواتب الولد المذكور، مع العلم بأن هذا الولد قائم بنفقة أولاده ووالديه وإخوانه؛ لأنهم في بيت واحد، فأحب والده أن يتبرع لابنه المذكور بخمس المال الذي بيده، مقابل عن عمله ودخله.","title":"هل للوالد أن يخص بعض أولاده بشيء دون الباقين؟","answer":"الجواب:\n\nقد ثبت عن النبي ﷺ أنه قال: اتقوا الله، واعدلوا بين أولادكم[1] متفق على صحته. فليس للوالد أن يخص بعض أولاده بشيء إلا برضا الباقين المكلفين المرشدين في أصح قولي العلماء. لكن إذا أحب أن يجعل ما قبضه من رواتبه في المستقبل قرضًا عليه، أو أمانة عنده، فلا بأس، وعليه أن يوضح ذلك في وثيقة معتمدة، وبذلك يكون قد حفظ له حقه الذي دخل عليه أو بعضه، ولا يكون أعطاه شيئًا، وإنما هو ماله حفظه له. والله أعلم[2].\n\n\n\n\tرواه البخاري في (الهبة وفضلها)، باب (الإشهاد في الهبة)، برقم: 2587، ومسلم في (الهبات)، باب (كراهة تفضيل بعض الأولاد في الهبة)، برقم: 1623.\n\tاستفتاء مقدم لسماحته من السائل /أ. ع. ن، وأجاب عنه سماحته برقم 841، في 25/3/1395هـ، عندما كان رئيسًا للجامعة الإسلامية. (مجموع فتاوى ومقالات الشيخ ابن باز 20/49).","link":"https://binbaz.org.sa/fatwas/19053/هل-للوالد-ان-يخص-بعض-اولاده-بشيء-دون-الباقين","audio":"","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19694,"question":"في حالة اختلاف شخصين على مال، وتحكيم ثالث بينهما، واغتصاب الثالث شيئًا من هذا المال بموافقتنا هل يحل له ذلك أم يحرم عليه؟","title":"جواز قبول الهبة لفاعل المعروف","answer":"الجواب:\n\nإذا حكَّم شخصان ثالثًا بينهما في مالٍ، فأخذ منه شيئًا بإذنهما وموافقتهما فلا أعلم فيه بأسًا، ولا يسمى ذلك اغتصابًا، بل هو هبة منهما له. أما إن شرط عليهما أن لا يحكم بينهما إلا بجعل، فهذا في حله نظر وتفصيل[1].\n\n\n\n\tمجموع فتاوى ومقالات الشيخ ابن باز (20/62).","link":"https://binbaz.org.sa/fatwas/19089/جواز-قبول-الهبة-لفاعل-المعروف","audio":"","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]}]
